-- ============================================================================
-- V222: 语文[职高] 题库补充 — 覆盖全部考纲模块
-- 基于 v127/v179/v180 节点体系，为每个 L4 知识点补充3~5题
-- 面向: 四川省对口高考语文 · 幂等: INSERT IGNORE
-- 2026-07-25 · 总计: 277 题
-- ============================================================================
SET NAMES utf8mb4;
START TRANSACTION;

-- 确保"调查报告"节点存在（应用文写作新增）
SET @l3_yyw = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=3 AND name='应用文写作' LIMIT 1);
INSERT IGNORE INTO knowledge_nodes (parent_id, subject_id, level, name, sort_order, created_at, updated_at)
VALUES (@l3_yyw, 20, 4, '调查报告', 13, NOW(), NOW());

-- ============================================================================
-- 一、字音字形 (8 nodes)
-- ============================================================================

-- --------------------------------------------------------------------------
-- 1. 多音字辨析
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='多音字辨析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列词语中加点字的读音，全部正确的一项是（　　）', '[{"key":"A","text":"反省（shěng）　粗犷（guǎng）"},{"key":"B","text":"强迫（qiǎng）　提防（dī）"},{"key":"C","text":"倔强（juè）　参差（cī）"},{"key":"D","text":"给予（gěi）　劲敌（jìn）"}]', 'B', 'A项"反省"的"省"应读xǐng；C项"倔强"的"倔"应读jué；D项"给予"的"给"应读jǐ，"劲敌"的"劲"应读jìng。B项全部正确。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列词语中，读音全都正确的一组是（　　）', '[{"key":"A","text":"薄纸（báo）　薄荷（bò）　薄弱（bó）"},{"key":"B","text":"变色（biàn）　方便（biàn）　便宜（biàn）"},{"key":"C","text":"处理（chù）　处所（chǔ）　处长（chù）"},{"key":"D","text":"伟大（wěi）　伪劣（wěi）　为位（wěi）"}]', 'A', 'A项"薄"在不同词语中读音正确：báo（纸张薄）、bò（薄荷）、bó（薄弱）。B项"便宜"应读pián yí；C项"处理"应读chǔ lǐ；D项"为位"的"为"应读wèi。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"强"字在"倔强"中读qiáng，在"强迫"中读qiǎng。', NULL, 'F', '"倔强"中的"强"应读jiàng，表示固执强硬不屈；"强迫"中的"强"读qiǎng，表示勉强、迫使。三种读音qiáng/qiǎng/jiàng均需掌握。', 2, 1),
('语文[职高]', @n, 'FILL_IN', '请写出"得"字在"获得"中读___，在"走得快"中读___，在"可得注意"中读___。', NULL, 'dé|de|děi', '"得"是多音字：获得（dé，得到）、走得快（de，程度补语）、可得注意（děi，必须、需要）。职高学生需重点掌握三个读音的区分。', 3, 1);

-- --------------------------------------------------------------------------
-- 2. 形近字辨析
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='形近字辨析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列词语中没有错别字的一项是（　　）', '[{"key":"A","text":"烦躁　急躁　干燥"},{"key":"B","text":"烦躁　急躁　干燥"},{"key":"C","text":"烦躁　急燥　干燥"},{"key":"D","text":"烦燥　急躁　干燥"}]', 'A', '"烦躁"和"急躁"的"躁"意为性急、不冷静，偏旁应为"足"（躁）；"干燥"的"燥"意为缺少水分，偏旁应为"火"（燥）。B、C、D均有字形错误。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各组词语中，字形全部正确的一组是（　　）', '[{"key":"A","text":"茶毒　荼叶　如火如荼"},{"key":"B","text":"针砭　贬低　针贬时弊"},{"key":"C","text":"徒劳　迁徙　陡峭"},{"key":"D","text":"瞋目　嗔怪　瞠目结舌"}]', 'C', 'A项应为"荼毒、茶叶、如火如荼"（"茶"与"荼"形近混淆）；B项应为"针砭时弊"（"砭"是古代治病石针，非"贬"）；D项"瞋目"应为"瞠目"（chēng mù，瞪着眼睛）。C项全部正确。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"戍守"的"戍"字中间是一点，"戊戌"的"戌"字中间是一横，"甲乙丙丁戊"的"戊"字中间是空的。', NULL, 'T', '三个形近字的辨记口诀：横戌（xū）点戍（shù）戊（wù）中空。左边撇为戌字，右边竖为戍字。学生可用口诀记忆。', 2, 1);

-- --------------------------------------------------------------------------
-- 3. 易读错字
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='易读错字' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列加点字读音全部正确的一项是（　　）', '[{"key":"A","text":"唾沫（tuò）　发酵（jiào）　畸形（jī）"},{"key":"B","text":"酗酒（xiōng）　怪癖（pǐ）　嗔怪（chēn）"},{"key":"C","text":"泥淖（zhào）　挟持（xiá）　桎梏（gào）"},{"key":"D","text":"蹉跎（cuō）　囹圄（wú）　包庇（pì）"}]', 'A', 'A项全部正确。B项"酗酒"应读xù；C项"泥淖"应读nào，"挟持"应读xié，"桎梏"应读zhì gù；D项"囹圄"应读líng yǔ，"包庇"应读bì。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列词语中，加点字读音有错误的一项是（　　）', '[{"key":"A","text":"毗邻（pí）　翩跹（xiān）　缄默（jiān）"},{"key":"B","text":"档案（dàng）　联袂（mèi）　哺育（bǔ）"},{"key":"C","text":"悭吝（jiān）　市侩（kuì）　亵渎（xiè）"},{"key":"D","text":"铸造（zhù）　砧板（zhēn）　炽热（chì）"}]', 'C', 'C项"悭吝"应读qiān lìn（意为吝啬），"市侩"应读shì kuài（指唯利是图的人）。A、B、D项读音均正确。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"发酵"的"酵"字正确读音是xiào，而不是jiào。', NULL, 'F', '"酵"的正确读音是jiào，不是xiào。这是一个高频易读错字，职高学生需重点记忆。类似的还有"酵母""发酵粉"。', 1, 1);

-- --------------------------------------------------------------------------
-- 4. 易写错字
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='易写错字' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列词语书写全部正确的一项是（　　）', '[{"key":"A","text":"精兵减政　变本加利　不可思义"},{"key":"B","text":"谈笑风声　直接了当　鬼鬼崇崇"},{"key":"C","text":"迫不及待　川流不息　一如既往"},{"key":"D","text":"黄梁美梦　金壁辉煌　一愁莫展"}]', 'C', 'A项应为"精兵简政、变本加厉、不可思议"；B项应为"谈笑风生、直截了当、鬼鬼祟祟"；D项应为"黄粱美梦、金碧辉煌、一筹莫展"。C项全部正确。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，没有错别字的一项是（　　）', '[{"key":"A","text":"这是最后的决择，我们必须慎重考虑。"},{"key":"B","text":"中国女排的拼博精神值得我们学习。"},{"key":"C","text":"我们要遵纪守法，不能以身试法。"},{"key":"D","text":"他性格急燥，容易冲动。"}]', 'C', 'A项"决择"应为"抉择"；B项"拼博"应为"拼搏"；D项"急燥"应为"急躁"。C项"以身试法"写法正确，意为明知违法还要去做。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '成语填空：___（默）守成规、___（呕）心沥血、再接再___（厉）、___（滥）竽充数。', NULL, '墨|呕|厉|滥', '"墨守成规"（墨子守城故事，非"默"）、"呕心沥血"（呕出心，非"沤"）、"再接再厉"（古指斗鸡磨嘴，非"励"）、"滥竽充数"（滥，失实。非"烂"）。', 2, 1);

-- --------------------------------------------------------------------------
-- 5. 同音字辨析
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='同音字辨析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '依次填入下列横线处的词语，最恰当的一组是（　　）\n①我们要___守交通规则。\n②他___然答应了我们的请求。\n③这是一次史无前___的壮举。', '[{"key":"A","text":"遵　慨　例"},{"key":"B","text":"尊　慨　列"},{"key":"C","text":"遵　概　列"},{"key":"D","text":"尊　概　例"}]', 'A', '"遵守"用"遵"（遵从）；"慨然"用"慨"（慷慨爽快）；"史无前例"用"例"（先例）。注意区分：尊（尊敬）、遵（遵守）；慨（感慨）、概（大概）；例（例子）、列（排列）。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '依次填入各句横线处的汉字，正确的一项是（　　）\n①这件事不能___（怨/愿）他。\n②我们要___（即/既）刻出发。\n③这是一段难忘的回___（忆/亿）。', '[{"key":"A","text":"怨　即　忆"},{"key":"B","text":"愿　即　忆"},{"key":"C","text":"怨　既　忆"},{"key":"D","text":"怨　即　亿"}]', 'A', '"怨"（埋怨）与"愿"（愿望）不同，"不能怨他"表示不能责怪他；"即刻"表示立即、马上，"既"表示已经；"回忆"的"忆"是记忆之意，"亿"是数目单位。注意区分这些常见的同音字。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '依次填入横线处的汉字，完全正确的一项是（　　）\n计___成功　___然一新　___心沥血　___名而来', '[{"key":"A","text":"划　焕　呕　慕"},{"key":"B","text":"画　换　呕　幕"},{"key":"C","text":"划　焕　沤　幕"},{"key":"D","text":"画　换　沤　慕"}]', 'A', '"计划"用"划"（方案）；"焕然一新"用"焕"（光明、光亮）；"呕心沥血"用"呕"（吐出，非"沤"意为浸泡）；"慕名而来"用"慕"（仰慕，非"幕"意为帐幕）。', 2, 1),
('语文[职高]', @n, 'FILL_IN', '请填写正确的汉字：\n（___）往直前（勇）　无可（___）何（奈）　（___）水相逢（萍）　迫不（___）待（及）', NULL, '勇|奈|萍|及', '"勇往直前"（勇敢）、"无可奈何"（奈何）、"萍水相逢"（浮萍，喻偶然相遇）、"迫不及待"（急迫得不能等待）。', 1, 1);

-- --------------------------------------------------------------------------
-- 6. 拼音拼写规则
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='拼音拼写规则' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列拼音拼写完全正确的一项是（　　）', '[{"key":"A","text":"绿（lǜ）色　学习（xué xí）"},{"key":"B","text":"优秀（yoǔ xiù）　春天（chūen tiān）"},{"key":"C","text":"儿女（ér nǚ）　作家（zuǒ jiā）"},{"key":"D","text":"骄傲（jiāo ào）　河流（hé lióu）"}]', 'A', 'A项拼写全部正确。B项"优秀"的"优"应是yōu（iōu→you），"春天"的"春"应是chūn；C项"作家"的"作"应是zuò；D项"河流"的"流"应是liú。注意：j/q/x与ü相拼时ü上两点省略但读ü。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列词语中，声调标注正确的一项是（　　）', '[{"key":"A","text":"一模一样（yì mú yī yàng）"},{"key":"B","text":"不屈不挠（bù qū bù náo）"},{"key":"C","text":"一唱一和（yī chàng yī hè）"},{"key":"D","text":"不三不四（bù sān bù sì）"}]', 'D', 'A项"一样"的"一"应在"样"前读变调yí（第四声前变第二声）；B项"不屈"的"不"在第四声前应读bú；C项"一唱"的"一"在第四声前应读yí。D项"不"在第三声前读原调bù，全部正确。注意"一""不"的变调规则。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"饭店"的拼音应写作"fàn diàn"，其中两个音节都标声调，且两个音节之间要空格。', NULL, 'T', '双音节词拼写时，每个音节独立标声调，音节之间用空格分隔。"饭店"正确拼写为"fàn diàn"。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '''qù''（去）的韵母是___，其中"ü"上两点省略的原因是___。', NULL, 'ü|jqx与ü相拼省略两点', 'j、q、x与ü相拼时，ü上两点省略，写成u，但实际读音仍是ü。所以"去"的拼音拼写为qù，韵母是ü。类似的有"取"(qǔ)、"需"(xū)。', 2, 1);

-- --------------------------------------------------------------------------
-- 7. 汉字结构知识
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='汉字结构知识' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列汉字结构分类正确的一项是（　　）', '[{"key":"A","text":"左右结构：好、林、明、体"},{"key":"B","text":"上下结构：思、星、想、做"},{"key":"C","text":"半包围：这、边、树、病"},{"key":"D","text":"全包围：国、回、团、同"}]', 'A', 'A项全部是左右结构，正确。B项"做"是左中右结构，不是上下结构。C项"树"是左中右结构，不是半包围；半包围如：这、边、病、建。D项"同"是半包围结构（同字框），不是全包围。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列汉字中，结构与其他三项不同的一项是（　　）', '[{"key":"A","text":"想"},{"key":"B","text":"森"},{"key":"C","text":"众"},{"key":"D","text":"晶"}]', 'A', 'A项"想"是上下结构（"相"在上，"心"在下）。B"森"、C"众"、D"晶"都是品字形结构（三个相同部件堆叠）。注意区分汉字的不同结构类型。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"部首"是指汉字中具有表意功能的偏旁，例如"江"的部首是"氵"（三点水）。', NULL, 'T', '部首是字典中给汉字分类的标目，通常是由偏旁充当。"江"的部首是"氵"，与水有关。大多数形声字的部首表示汉字的义类。', 1, 1);

-- --------------------------------------------------------------------------
-- 8. 四川方言辨正
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='四川方言辨正' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '四川方言中，下列哪一组字的声母容易与普通话混淆？（　　）', '[{"key":"A","text":"z、c、s 与 zh、ch、sh"},{"key":"B","text":"b、p、m 与 d、t、n"},{"key":"C","text":"g、k、h 与 j、q、x"},{"key":"D","text":"zh、ch、sh 与 r"}]', 'A', '四川方言（特别是成都、重庆片）平翘舌不分是最突出的特征之一。如"四"(sì)与"十"(shí)、"资"(zī)与"知"(zhī)读音混同。这是四川人学习普通话的重点难点。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列词语中，加点字在四川方言中容易读错的一项是（　　）', '[{"key":"A","text":"那（nà）个　他（tā）"},{"key":"B","text":"飞（fēi）机　灰（huī）色"},{"key":"C","text":"脑（nǎo）袋　老（lǎo）人"},{"key":"D","text":"牛（niú）奶　流（liú）水"}]', 'C', '四川方言中鼻音n和边音l普遍不分（称"鼻边音不分"），"脑袋"(nǎo)和"老人"(lǎo)读成相同声母。A项"那""他"一般区分；B项h/f在部分四川话中相混，但不是最普遍；D项"牛""流"鼻边音问题同样存在，但C是典型代表。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '四川方言辨正：下列句子中加点字读音需要重点注意平翘舌区分的是（　　）', '[{"key":"A","text":"这（zhè）是我的书（shū）。"},{"key":"B","text":"他（tā）去（qù）了教室。"},{"key":"C","text":"天（tiān）气很好（hǎo）。"},{"key":"D","text":"我（wǒ）是学（xué）生。"}]', 'A', 'A项"这"(zhè)和"书"(shū)都是翘舌音（zh、ch、sh），四川方言中容易读成平舌音zè和sū。B、C、D项的字在四川话中与普通话差别不大。四川方言辨正需重点训练平翘舌、鼻边音、h/f等。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '四川方言中，h和f是容易混淆的声母，例如"花(huā)"被读成"发(fā)"。', NULL, 'T', '部分四川方言（如重庆、川东片区）存在h/f混读现象，如"花"(huā)读成"发"(fā)、"黄"(huáng)读成"房"(fáng)。这是四川人学习普通话需要纠正的重点之一。', 1, 1);

-- ============================================================================
-- 二、词语运用 (5 nodes)
-- ============================================================================

-- --------------------------------------------------------------------------
-- 9. 近义词辨析
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='近义词辨析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '依次填入下列各句横线处的词语，最恰当的一组是（　　）\n①他是一个性格___的人，做事从不急躁。\n②由于长期___，他的身体越来越差。\n③我们要___时间，努力学习。', '[{"key":"A","text":"沉稳　劳累　珍惜"},{"key":"B","text":"沉稳　劳碌　珍视"},{"key":"C","text":"稳重　劳累　珍惜"},{"key":"D","text":"稳重　劳碌　珍视"}]', 'C', '"稳重"侧重言行举止不轻浮，"沉稳"侧重性格沉着冷静，形容人用"稳重"更恰当；"劳累"侧重体力消耗，"劳碌"侧重奔波忙碌，身体变差用"劳累"；"珍惜"比"珍视"更能体现对时间的珍爱、不浪费。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中加点词语使用不恰当的一项是（　　）', '[{"key":"A","text":"老师（嘱咐）我们路上要注意安全。"},{"key":"B","text":"他（委托）我帮他办理这件事。"},{"key":"C","text":"交警（叮嘱）司机不要酒后驾车。"},{"key":"D","text":"母亲（吩咐）我去买瓶酱油。"}]', 'B', 'B项"委托"意为请人代办，语气较为正式，此处用"拜托"或"托付"更自然。A项"嘱咐"（叮嘱、告诉）、C项"叮嘱"（反复提醒、语气较重）、D项"吩咐"（口头指派）使用均恰当。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"成果""结果""后果"三个词都表示事物发展的结局，但感情色彩不同："成果"褒义，"结果"中性，"后果"贬义。', NULL, 'T', '这三个近义词反映了词语的感情色彩差异。"成果"（如科研成果）含褒义；"结果"（如考试结果）中性客观；"后果"（如交通违章的后果）通常含贬义。这是近义词辨析的重要维度。', 1, 1);

-- --------------------------------------------------------------------------
-- 10. 成语使用正误
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='成语使用正误' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中加点成语使用恰当的一项是（　　）', '[{"key":"A","text":"他总是不（求甚解），所以成绩一直提不上去。"},{"key":"B","text":"老师（夸夸其谈）地讲了一堂课，同学们收获很大。"},{"key":"C","text":"同学们（聚精会神）地听劳模作报告。"},{"key":"D","text":"整个会场（人声鼎沸），大家都在安静地听讲。"}]', 'C', 'C项"聚精会神"形容注意力高度集中，使用正确。A项"不求甚解"多指读书不深入，用于学习态度可以，但语境更适合"马马虎虎"或"粗心大意"；B项"夸夸其谈"是贬义词，形容说话浮夸不切实际，不能用于褒义的评价；D项"人声鼎沸"形容人声嘈杂喧闹，与"安静地听讲"矛盾。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中加点成语使用错误的一项是（　　）', '[{"key":"A","text":"成都大运会上，中国健儿们（脱颖而出），取得了优异成绩。"},{"key":"B","text":"他上课总是（心不在焉），注意力不够集中。"},{"key":"C","text":"老师（耳提面命）地教导我们做人做事的道理。"},{"key":"D","text":"经过努力，这家工厂的效益有了很大的（起色）。"}]', 'C', 'C项"耳提面命"用词不当。"耳提面命"是褒义词，形容教诲殷切恳切，但通常用于长辈对晚辈的郑重教导，不宜用于课堂日常教学场景。这里可用"语重心长"或"谆谆教诲"。A"脱颖而出"、B"心不在焉"、D"起色"使用均正确。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，加点成语使用恰当的一项是（　　）', '[{"key":"A","text":"他这次考了第一名，真是（名落孙山）。"},{"key":"B","text":"街上车水马龙，（门可罗雀），一片繁华景象。"},{"key":"C","text":"大家（不约而同）地站起来为他鼓掌。"},{"key":"D","text":"他在这件事上（首当其冲），获得了第一名的好成绩。"}]', 'C', 'C项"不约而同"指没有事先约定而彼此一致，使用正确。A项"名落孙山"比喻考试落榜或选拔未被录取，与"考了第一名"矛盾；B项"门可罗雀"形容门庭冷清，与"繁华景象"矛盾；D项"首当其冲"比喻最先受到攻击或遭遇灾难，不能用于获得好成绩。', 2, 1);

-- --------------------------------------------------------------------------
-- 11. 关联词语搭配
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='关联词语搭配' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '依次填入下列横线处的关联词语，最恰当的一组是（　　）\n___我们努力学习，___能掌握专业技能，___有了一份本领，___能找到理想的工作。', '[{"key":"A","text":"只有　才　只要　就"},{"key":"B","text":"只要　就　只有　才"},{"key":"C","text":"因为　所以　只要　就"},{"key":"D","text":"如果　就　才　才"}]', 'A', '第一层"只有……才"表示必要条件（努力是掌握技能的必要条件）；第二层"只要……就"表示充分条件（有了本领就能找到工作）。A项逻辑关系最准确。B项因果倒置，C项因果关系不合适，D项假设关系不准确。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中关联词语使用不正确的一项是（　　）', '[{"key":"A","text":"（无论）困难有多大，我们（也）要坚持到底。"},{"key":"B","text":"（只要）我们有信心，（就）能克服困难。"},{"key":"C","text":"（不管）任务多么艰巨，我们（都）要努力完成。"},{"key":"D","text":"他（不但）学习好，（而且）品德高尚。"}]', 'A', 'A项"无论……也"搭配不当，"无论"通常与"都"搭配，表示在任何条件下结果都一样，应改为"无论困难有多大，我们都要坚持到底"。B、C、D项关联词语搭配正确。"只要……就"表充分条件，"不管……都"表无条件，"不但……而且"表递进。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '依次填入下面句子横线处的关联词语，最恰当的一项是（　　）\n___现在专业技能过硬，___将来步入社会___能有竞争力。___不断学习新知识，___能跟上时代发展的步伐。', '[{"key":"A","text":"只有　才　才　只有　才"},{"key":"B","text":"只要　就　就　只要　就"},{"key":"C","text":"因为　所以　就　如果　就"},{"key":"D","text":"虽然　但是　就　只要　才"}]', 'A', '两个分句都是"只有……才"条件关系：过硬的专业技能是具备竞争力的必要条件；不断学习是跟上时代步伐的必要条件。A项正确，B项"只要……就"表充分条件，语气不如"只有……才"严谨。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"无论……都"是一对关联词语，表示条件关系，意思是"在任何条件下结果都不变"。', NULL, 'T', '"无论……都"表示无条件关系（条件关系的一种），即不管条件如何变化，结果都不会改变。例如"无论天气多冷，他都坚持晨跑"。', 1, 1);

-- --------------------------------------------------------------------------
-- 12. 词语的感情色彩与语体色彩
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='词语的感情色彩与语体色彩' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各组词语中，感情色彩完全相同的一组是（　　）', '[{"key":"A","text":"成果　结果　后果"},{"key":"B","text":"顽强　顽固　坚强"},{"key":"C","text":"领导人　头目　首脑"},{"key":"D","text":"宏大　巨大　庞大"}]', 'D', 'D项"宏大""巨大""庞大"都是中性词，表示大，感情色彩一致。A项"成果"褒义、"结果"中性、"后果"贬义；B项"顽强""坚强"褒义、"顽固"贬义；C项"领导人"中性、"头目"贬义、"首脑"褒义。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，加点词语语体色彩使用恰当的一项是（　　）', '[{"key":"A","text":"在毕业典礼上，校长进行了（讲话）。（讲话为口语，正式场合应用"致辞"）"},{"key":"B","text":"请把你的身份证（呈）上来让我看看。（"呈"为书面语敬辞，用于普通场合过于正式）"},{"key":"C","text":"医生（叮嘱）病人按时服药。（"叮嘱"为书面语，用于医嘱恰当）"},{"key":"D","text":"我家（犬子）今年考上了中职学校。（"犬子"为谦辞，指自己儿子，使用恰当）"}]', 'C', 'C项"叮嘱"语体色彩恰当（医嘱场景用词恰当）。A项正式场合用"致辞"比"讲话"更得体；B项"呈"是敬辞（呈报上级），对普通人用"拿"或"递"即可；D项"犬子"虽是谦辞，但在日常口语中使用会显得过于文绉绉，不太自然。注意语体色彩要与场合匹配。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"吝啬"与"节俭"都表示节约，但"吝啬"是贬义词，"节俭"是褒义词，两者感情色彩不同。', NULL, 'T', '"吝啬"指过分爱惜钱财、当用不用，含贬义；"节俭"指节约俭省，含褒义。同样是节约行为，前者贬损后者褒扬，体现了感情色彩对词义的影响。', 1, 1);

-- --------------------------------------------------------------------------
-- 13. 常用熟语与惯用语
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='常用熟语与惯用语' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中加点熟语使用不恰当的一项是（　　）', '[{"key":"A","text":"做事不能（三天打鱼，两天晒网），要坚持不懈。"},{"key":"B","text":"他这个人总是（这山望着那山高），做什么都不踏实。"},{"key":"C","text":"老师常说（"吃一堑，长一智"），我们要从失败中吸取教训。"},{"key":"D","text":"这件事我们已经（打开天窗说亮话），大家都明白了吧。"}]', 'D', 'D项"打开天窗说亮话"比喻毫不隐讳地说明，一般用于说话者表明态度，此处语境是对话结束后的确认，用"说清楚"或"说明白"更合适。A、B、C项熟语使用均正确。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列惯用语解释不正确的一项是（　　）', '[{"key":"A","text":""绊脚石"——比喻阻碍前进的人或事物"},{"key":"B","text":""炒鱿鱼"——比喻被单位开除或解雇"},{"key":"C","text":""马后炮"——比喻行动迅速、办事利索"},{"key":"D","text":""敲边鼓"——比喻从旁帮腔、助势"}]', 'C', 'C项"马后炮"比喻事情已经发生后才提出建议或采取行动，为时已晚，并非"行动迅速"。A、B、D项解释均正确。惯用语通俗形象，掌握其实际含义对提高语言表达能力很有帮助。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"唱对台戏"的意思是表演人员同台演出精彩的节目，大家相互配合。', NULL, 'F', '"唱对台戏"比喻采取与对方相对立的行动，或故意对着干，并非指配合演出。类似容易误解的惯用语还有"跑龙套"（比喻做无关紧要的杂事，非指实际跑动）。', 2, 1);

-- ============================================================================
-- 三、病句辨析 (6 nodes)
-- ============================================================================

-- --------------------------------------------------------------------------
-- 14. 语序不当
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='语序不当' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，没有语病的一项是（　　）', '[{"key":"A","text":"我们要认真改正并找出作业中的错误。"},{"key":"B","text":"学校开展了一系列丰富多彩的校园文化活动。"},{"key":"C","text":"他不但学习好，而且身体也好，所以。"},{"key":"D","text":"同学们纷纷地表达了自己对未来的决心和信心。"}]', 'B', 'B项表达正确。A项语序不当，应先"找出"再"改正"，应为"找出并改正"；C项"所以"多余，删去；D项"纷纷地"和"表达"搭配不当，且"决心和信心"语义重复，可改为"纷纷表达了对未来的信心"。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，没有语病且语序正确的一项是（　　）', '[{"key":"A","text":"通过这次实训，使我们掌握了基本的操作技能。"},{"key":"B","text":"这是一次十分极其重要的比赛。"},{"key":"C","text":"老师耐心地给我们讲解了操作步骤。"},{"key":"D","text":"他的写作水平有了明显的提高和改善。"}]', 'C', 'C项语序正确、表达通顺。A项"通过……使……"滥用介词导致主语缺失，应去掉"通过"或"使"；B项"十分"与"极其"语义重复，保留一个即可；D项"提高和改善"中"改善"与"水平"搭配不当，"水平"只能说"提高"。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"我们要发扬和继承优良传统。"这个句子语序不当，应先"继承"再"发扬"。', NULL, 'T', '原句"发扬和继承"语序不当，应该先"继承"（接受前人遗产），再"发扬"（发展光大）。改为"继承和发扬"。类似结构：发现并解决问题、总结并推广经验。', 2, 1);

-- --------------------------------------------------------------------------
-- 15. 搭配不当
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='搭配不当' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，没有搭配不当语病的一项是（　　）', '[{"key":"A","text":"他的写作水平有了明显的增加。"},{"key":"B","text":"秋天的成都是一年中最美的季节。"},{"key":"C","text":"我们要养成按时完成作业的好习惯。"},{"key":"D","text":"随着经济的发展，人民的生活水平正在不断地改善。"}]', 'C', 'C项"养成……习惯"搭配正确。A项"水平"不能"增加"，应改为"提高"；B项主宾搭配不当，"秋天"是季节，不能说"成都是季节"，应改为"成都的秋天是一年中最美的季节"；D项"水平"与"改善"搭配不当，"水平"应搭配"提高"，"生活"才能"改善"。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，没有搭配不当语病的一项是（　　）', '[{"key":"A","text":"他的感人事迹深深地打动了在场的每一位观众。"},{"key":"B","text":"他提出并发现了这个问题。"},{"key":"C","text":"我们要增强学习的习惯。"},{"key":"D","text":"听了劳模的报告，使我很受感动。"}]', 'A', 'A项"事迹打动观众"搭配恰当。B项语序不当，应先"发现"后"提出"；C项"增强"与"习惯"搭配不当，应改为"培养习惯"或"增强意识"；D项"听了……使……"导致主语缺失（介词结构淹没主语）。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"随着城市化进程加快，该市的人口数量显著地提高了。"这句话中"数量"与"提高"搭配不当，应改为"数量增加"或"数量增长"。', NULL, 'T', '"数量"不能用"提高"搭配，应用"增加""增长"或"上升"。"提高"多用于水平、能力、效率等抽象概念。如"提高水平""提高效率"。', 2, 1);

-- --------------------------------------------------------------------------
-- 16. 成分残缺或赘余
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='成分残缺或赘余' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，没有语病的一项是（　　）', '[{"key":"A","text":"通过这次实习，使我学到了很多书本上学不到的知识。"},{"key":"B","text":"目前，我国大部分地区进入了流感高发季节。"},{"key":"C","text":"当听到这个好消息时，他的脸上露出了。"},{"key":"D","text":"他大约四十岁上下的年纪，中等身材。"}]', 'B', 'B项句子完整，表述正确。A项"通过……使……"导致主语缺失（滥用介词），应删除"通过"或"使"；C项"露出"后缺少宾语，应在句末加"笑容"；D项"大约"和"上下"语义重复，应删去其一（成分赘余）。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，成分残缺的一项是（　　）', '[{"key":"A","text":"中国人民正在努力为建设一个现代化的社会主义强国。"},{"key":"B","text":"这篇文章的内容和见解都很丰富。"},{"key":"C","text":"他做事总是很认真负责。"},{"key":"D","text":"同学们都按时完成了作业。"}]', 'A', 'A项成分残缺，"为……强国"后面缺少谓语中心语，应加上"而奋斗"之类的动词，构成"为建设……而努力奋斗"。B项"内容"与"丰富"搭配正确，但"见解"与"丰富"不搭配，属搭配不当；C、D项表述完整。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"我大约用了整整两个小时才完成这份作业。"这句话中"大约"与"整整"语义矛盾且赘余，应去掉其中一个。', NULL, 'T', '"大约"表示不确定的估计，"整整"表示精确的整数，两者放在一起矛盾且赘余。应改为"我大约用了两个小时"或"我用了整整两个小时"。', 1, 1);

-- --------------------------------------------------------------------------
-- 17. 结构混乱
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='结构混乱' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，没有结构混乱语病的一项是（　　）', '[{"key":"A","text":"对于这种浪费资源的现象，至今没有引起相关部门的重视。"},{"key":"B","text":"这是值得每一个中职学生值得思考的问题。"},{"key":"C","text":"由于他良好的表现，被学校评为优秀学生干部。"},{"key":"D","text":"作为新时代的青年，我们要肩负起建设祖国的重任。"}]', 'D', 'D项句子结构清晰，表述正确。A项"对于……"介词结构导致主语缺失（结构混乱，应去掉"对于"）；B项"值得"重复使用（句式杂糅，应删去后一个"值得"）；C项"由于"和"被"连用导致主语缺失（去掉"由于"或补充主语。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，属于结构混乱语病的一项是（　　）', '[{"key":"A","text":"我们要养成按时完成作业的习惯。"},{"key":"B","text":"老师耐心地教导我们要认真学习。"},{"key":"C","text":"他的写作水平有了明显的提高。"},{"key":"D","text":"这次技能大赛，是展示自己专业技能的一次很好机会，值得我们珍惜。"}]', 'D', 'D句句式杂糅：前半句"是展示……的机会"与后半句"值得我们珍惜"两个句式被混在一起。应改为"这次技能大赛是展示自己专业技能的好机会，值得我们珍惜"或"这次技能大赛，既展示了自己的专业技能，又值得我们珍惜"。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"基地的秋天是一个丰收的季节。"这句话存在结构混乱的语病。', NULL, 'F', '这句话没有结构混乱的问题。"基地的秋天是……季节"主宾虽然搭配不当（秋天不能是季节的种属），但这是"搭配不当"语病，而非"结构混乱"。结构混乱是指句式杂糅、中途易辙、反客为主等。', 3, 1);

-- --------------------------------------------------------------------------
-- 18. 表意不明（歧义句）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='表意不明（歧义句）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，表意明确、没有歧义的一项是（　　）', '[{"key":"A","text":"他的发型真好看。"},{"key":"B","text":"开刀的是他父亲。"},{"key":"C","text":"我们三个人一组。"},{"key":"D","text":"他借我五百元钱。"}]', 'A', 'A项表意明确。B项"开刀的"既可以指执刀的医生，也可以指接受手术的病人，有歧义；C项"三个人一组"可以理解为"我们/三个人一组"（每三人一组），也可以理解为"我们三个人/一组"（我们是同一组），停顿不同意思不同；D项"借"既可以是"借出"也可以是"借入"，方向不明。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，有歧义的一项是（　　）', '[{"key":"A","text":"他正在会议室里开会。"},{"key":"B","text":"他的笑话讲不完。"},{"key":"C","text":"我今天上午去了图书馆。"},{"key":"D","text":"他是一位经验丰富的教师。"}]', 'B', 'B句"他的笑话讲不完"有歧义：既可以理解为"他讲的笑话（故事）讲不完"，也可以理解为"关于他的（可笑之事）讲不完"。A、C、D句表意明确。歧义句在语言交际中应尽量避免。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，没有歧义的一项是（　　）', '[{"key":"A","text":"我背着妹妹去了医院。"},{"key":"B","text":"看到你那年才六岁。"},{"key":"C","text":"今天下午我要去银行汇款。"},{"key":"D","text":"他一个人做不完这些事，我们都要帮忙。"}]', 'C', 'C项表意明确。A项"背着"有歧义：可指"背（bēi）着"（用背驮着），也可指"背（bèi）着"（瞒着、偷偷地）；B项"看到你那年才六岁"主语不明，是"我"六岁还是"你"六岁；D项"我们都要帮忙"中"都"可能指"全部"（所有人帮忙），也可能指"必须"（应该帮忙），且"帮忙"的对象不明确。', 3, 1);

-- --------------------------------------------------------------------------
-- 19. 不合逻辑
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='不合逻辑' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，没有不合逻辑语病的一项是（　　）', '[{"key":"A","text":"我们班的出勤率基本上全部达到了。"},{"key":"B","text":"他是多个死难者中幸免的一个。"},{"key":"C","text":"为了防止此类安全事故不再发生，学校加强了管理。"},{"key":"D","text":"那辆大卡车突然停了下来，原来是前面红灯亮了。"}]', 'D', 'D项逻辑合理。A项"基本上"与"全部"自相矛盾；B项"死难者中幸免"自相矛盾（死难者已死亡，不可能"幸免"）；C项"防止……不再发生"否定不当，等于"要让事故发生"，应去掉"不"或改"防止"为"让"。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，不合逻辑的一句是（　　）', '[{"key":"A","text":"我国有世界上没有的万里长城。"},{"key":"B","text":"他已经连续工作十几个小时了。"},{"key":"C","text":"因为他平时训练刻苦，所以在比赛中取得了好成绩。"},{"key":"D","text":"这个商店的商品价格便宜，质量也很好。"}]', 'A', 'A句不合逻辑，"我国"是"世界"的一部分，"我国有世界上没有的"自相矛盾。应改为"我国有世界上其他国家没有的万里长城"或"万里长城在世界上独一无二"。B、C、D句逻辑合理。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他是中等身材，穿着一件灰色衣服和帽子。"这句话存在不合逻辑的语病。', NULL, 'T', '这句话属于不合逻辑中的"概念并列不当"——"穿"可以搭配"衣服"，但不能搭配"帽子"（帽子是"戴"）。应改为"穿着一件灰色衣服，戴着一顶帽子"。此类语病是将不同类别的事物强行并列。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"能否刻苦学习，是取得好成绩的关键。"这句话存在不合逻辑（两面对一面）的语病。', NULL, 'T', '"能否"是两面词（能与不能），而"取得好成绩"是一面结果。正确表达应为"刻苦学习是取得好成绩的关键"或"能否刻苦学习，是能否取得好成绩的关键"。这种"两面对一面"是常见的不合逻辑语病。', 2, 1);

