-- --------------------------------------------------------------------------
-- 1. 论述文阅读（论点·论据·论证）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='论述文阅读（论点·论据·论证）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '议论文中，作者对所论述问题提出的见解和主张称为（　　）', '[{"key":"A","text":"论据"},{"key":"B","text":"论证"},{"key":"C","text":"论点"},{"key":"D","text":"结论"}]', 'C', '论点是作者的核心观点，是议论文的灵魂。论据是支撑论点的材料，论证是用论据证明论点的过程。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '《师说》中"孔子师郯子、苌弘、师襄、老聃"运用的论证方法是（　　）', '[{"key":"A","text":"比喻论证"},{"key":"B","text":"举例论证"},{"key":"C","text":"道理论证"},{"key":"D","text":"对比论证"}]', 'B', '作者用孔子向多人请教的具体事例来论证"圣人无常师"的论点，属于举例论证（例证法）。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '议论文的论据包括事实论据和道理论据两大类。', NULL, 'T', '事实论据包括具体事例、统计数据等，道理论据包括名人名言、科学原理等。', 1, 1);

-- --------------------------------------------------------------------------
-- 2. 说明文阅读（说明方法·说明顺序）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='说明文阅读（说明方法·说明顺序）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"这座石拱桥全长50.82米，宽9.6米，跨径37.4米"运用的说明方法是（　　）', '[{"key":"A","text":"举例子"},{"key":"B","text":"列数字"},{"key":"C","text":"打比方"},{"key":"D","text":"作比较"}]', 'B', '用具体准确的数据说明事物的特征，是列数字的说明方法，可使说明更精确、有说服力。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '说明文按照时间先后顺序来说明事物，这种顺序称为（　　）', '[{"key":"A","text":"空间顺序"},{"key":"B","text":"逻辑顺序"},{"key":"C","text":"时间顺序"},{"key":"D","text":"程序顺序"}]', 'C', '时间顺序按照事物发生发展的先后过程进行说明，常用于介绍工艺流程、历史变迁等。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '打比方这种说明方法等同于修辞手法中的比喻，两者没有区别。', NULL, 'F', '打比方是说明方法（用于说明事物特征），比喻是修辞手法（用于增强语言生动性），二者在目的和功能上有区别。', 2, 1);

-- --------------------------------------------------------------------------
-- 3. 信息筛选与整合
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='信息筛选与整合' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '信息筛选题最核心的解题方法是（　　）', '[{"key":"A","text":"凭记忆直接选"},{"key":"B","text":"先读题干，定位原文，逐词比对"},{"key":"C","text":"选择最长的选项"},{"key":"D","text":"根据常识判断"}]', 'B', '信息筛选题的关键是"于文有据"，必须回到原文定位相关内容，逐词比对选项与原文的差异。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列选项中，属于信息筛选题常见干扰方式的是（　　）', '[{"key":"A","text":"与原文完全一致"},{"key":"B","text":"偷换概念"},{"key":"C","text":"使用同义词替换"},{"key":"D","text":"调整语序"}]', 'B', '偷换概念是命题人常用的干扰手段，将原文中的某个概念换成相近但不同的概念，需仔细辨析。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '信息整合就是将原文中的句子直接抄写下来。', NULL, 'F', '信息整合是在理解原文的基础上，将分散在不同段落的信息进行归纳、概括和重组，不是简单抄写。', 2, 1);

-- --------------------------------------------------------------------------
-- 4. 分析推理与判断
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='分析推理与判断' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '原文说"该技术目前仍处于研发阶段"，据此推断合理的一项是（　　）', '[{"key":"A","text":"该技术已经成熟可商用"},{"key":"B","text":"该技术未来一定成功"},{"key":"C","text":"该技术目前尚不完善，仍需进一步研发"},{"key":"D","text":"该技术已经失败了"}]', 'C', '"处于研发阶段"说明尚未完全成熟，合理的推断是仍需继续研发。A和D都是过度推断，B过于绝对。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '分析推理时，下列做法正确的是（　　）', '[{"key":"A","text":"根据个人主观判断随意引申"},{"key":"B","text":"严格依据原文信息进行合理推断"},{"key":"C","text":"将所有可能情况都看作正确"},{"key":"D","text":"只关注结论不看论证过程"}]', 'B', '分析推理必须忠实于原文，不能随意添加原文没有的信息，也不能过度推断。"合理"是关键。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"无中生有"是分析推理题常见的错误类型，即原文中没有提及的信息出现在选项中。', NULL, 'T', '无中生有是命题人凭空捏造原文未提及的内容，考生需要仔细对照原文，不能凭印象选择。', 2, 1);

-- --------------------------------------------------------------------------
-- 5. 文章结构与论证逻辑
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='文章结构与论证逻辑' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '议论文"提出问题—分析问题—解决问题"的结构模式是（　　）', '[{"key":"A","text":"总分总式"},{"key":"B","text":"并列式"},{"key":"C","text":"递进式"},{"key":"D","text":"对照式"}]', 'C', '递进式结构逐层深入，由表及里，由现象到本质。"是什么—为什么—怎么办"是典型的递进式论证思路。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列选项中属于并列式论证结构的是（　　）', '[{"key":"A","text":"先提出论点，再从不同角度分别论证"},{"key":"B","text":"层层深入，由浅入深"},{"key":"C","text":"正反两方面对比论证"},{"key":"D","text":"开头结尾呼应"}]', 'A', '并列式是从几个平行的角度或方面分别论证同一个论点，各层次之间是并列关系，无主次之分。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '议论文中，结尾段的作用通常包括总结全文、重申论点、发出号召等。', NULL, 'T', '议论文结尾的作用多样：总结全文、呼应开头、深化论点、发出号召或展望未来。', 1, 1);

-- --------------------------------------------------------------------------
-- 6. 重要概念与关键句理解
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='重要概念与关键句理解' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '理解文中重要句子的含义时，正确的做法是（　　）', '[{"key":"A","text":"只看句子本身字面意思"},{"key":"B","text":"结合上下文语境，分析表层和深层含义"},{"key":"C","text":"用自己的理解随意发挥"},{"key":"D","text":"只看修辞手法"}]', 'B', '重要句子的理解需要联系上下文，既要把握字面意义（表层），也要挖掘语境意义（深层）。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '文中"这种精神的火种从未熄灭"中"火种"的深层含义是（　　）', '[{"key":"A","text":"真实的火焰"},{"key":"B","text":"某种精神或传统的延续"},{"key":"C","text":"火把的种子"},{"key":"D","text":"温度很高"}]', 'B', '"火种"在这里是比喻用法，深层含义是指某种精神、传统或信念的延续和传承，而非字面的火焰。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '理解重要概念时，只需根据词典定义即可，不需要结合文章具体语境。', NULL, 'F', '重要概念的含义往往受具体语境的制约，词典定义只是基础，必须结合语境才能准确理解。', 2, 1);

