-- --------------------------------------------------------------------------
-- 7. 小说阅读（人物·情节·环境）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='小说阅读（人物·情节·环境）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列选项中不属于小说三要素的是（　　）', '[{"key":"A","text":"人物"},{"key":"B","text":"情节"},{"key":"C","text":"环境"},{"key":"D","text":"主题"}]', 'D', '小说的三要素是人物、情节和环境。主题是作品的中心思想，不是三要素之一。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '小说情节的基本结构顺序是（　　）', '[{"key":"A","text":"开端—发展—高潮—结局"},{"key":"B","text":"开端—高潮—发展—结局"},{"key":"C","text":"发展—开端—高潮—结局"},{"key":"D","text":"结局—开端—发展—高潮"}]', 'A', '小说情节的一般结构是开端（交代背景引出矛盾）、发展（矛盾逐步展开）、高潮（矛盾最尖锐）、结局（矛盾解决）。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '小说中的自然环境描写主要是为了交代故事发生的时间和地点，有时也起到烘托人物心情的作用。', NULL, 'T', '自然环境描写的作用包括：交代时令地点、渲染气氛、烘托人物心情、推动情节发展等。', 2, 1);

-- --------------------------------------------------------------------------
-- 8. 散文阅读（形散神聚·情景交融）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='散文阅读（形散神聚·情景交融）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '散文"形散而神不散"中"神"指的是（　　）', '[{"key":"A","text":"神灵"},{"key":"B","text":"贯穿全文的中心思想和情感主线"},{"key":"C","text":"文章的篇幅"},{"key":"D","text":"作者的外貌"}]', 'B', '"神"是散文的灵魂，指统一的思想情感主线。"形散"指选材和表达方式灵活自由，"神聚"指始终围绕核心主题。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '朱自清《荷塘月色》中，作者借荷塘月色表达内心情感，这种表现手法是（　　）', '[{"key":"A","text":"托物言志"},{"key":"B","text":"借景抒情"},{"key":"C","text":"借古讽今"},{"key":"D","text":"以小见大"}]', 'B', '借景抒情是散文常用的手法——通过描写客观景物来抒发主观情感。荷塘月色是景，淡淡的喜悦和忧愁是情。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '散文的特点是"形散神聚"，因此散文可以随意堆砌材料，不需要围绕中心。', NULL, 'F', '散文虽然选材自由灵活（形散），但所有材料都必须服务于统一的主题（神聚），并非随意堆砌。', 2, 1);

-- --------------------------------------------------------------------------
-- 9. 表现手法辨析
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='表现手法辨析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '《白杨礼赞》中用白杨树象征北方农民的精神，这种表现手法是（　　）', '[{"key":"A","text":"对比"},{"key":"B","text":"象征"},{"key":"C","text":"夸张"},{"key":"D","text":"衬托"}]', 'B', '象征是用具体形象表现抽象概念或思想感情。白杨树的挺拔象征北方农民的坚韧不屈。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列选项中，属于表现手法（又称艺术手法）的是（　　）', '[{"key":"A","text":"比喻"},{"key":"B","text":"拟人"},{"key":"C","text":"象征"},{"key":"D","text":"排比"}]', 'C', '表现手法是篇章级的写作技巧，包括象征、对比、衬托、欲扬先抑、借景抒情等。比喻、拟人、排比属于修辞手法（语句级）。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '对比和衬托是同一种表现手法，都是把两个事物放在一起比较。', NULL, 'F', '对比是突出双方的差异（不分主次），衬托是一方为另一方服务（有主次之分）。例如"红花绿叶"是衬托，"胖瘦对比"是对比。', 3, 1);

-- --------------------------------------------------------------------------
-- 10. 表达方式及其作用
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='表达方式及其作用' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列选项中不属于文章五种基本表达方式的是（　　）', '[{"key":"A","text":"记叙"},{"key":"B","text":"描写"},{"key":"C","text":"抒情"},{"key":"D","text":"渲染"}]', 'D', '五种基本表达方式是：记叙、描写、说明、议论、抒情。"渲染"是表现手法，不是独立的表达方式。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"他的背影渐渐地消失在人群中"运用的主要表达方式是（　　）', '[{"key":"A","text":"记叙"},{"key":"B","text":"描写"},{"key":"C","text":"议论"},{"key":"D","text":"说明"}]', 'B', '这句话对"背影"进行了具体的形象刻画，属于描写中的细节描写。记叙重在交代过程，描写重在刻画形象。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '记叙文中，议论和抒情可以在记叙的基础上起到画龙点睛、深化主题的作用。', NULL, 'T', '记叙文以记叙为主，但适当加入议论和抒情可以增强文章的感染力，深化主题思想，起到画龙点睛的效果。', 2, 1);

-- --------------------------------------------------------------------------
-- 11. 人物形象分析
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='人物形象分析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '分析小说人物形象时，最可靠的依据是（　　）', '[{"key":"A","text":"读者的个人感受"},{"key":"B","text":"文章中关于人物的具体描写"},{"key":"C","text":"其他同学的看法"},{"key":"D","text":"影视作品的改编"}]', 'B', '人物形象分析必须"有理有据"，以文本中的外貌、语言、动作、心理、神态等具体描写为依据，不能脱离文本。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"他不说话，只是默默地把伞递到我的手里，转身走进了雨里"这段描写主要刻画了人物（　　）的品质', '[{"key":"A","text":"能言善辩"},{"key":"B","text":"沉默寡言且自私"},{"key":"C","text":"不善表达却真诚关爱"},{"key":"D","text":"粗心大意"}]', 'C', '人物的动作描写（默默递伞）展现了其不善言辞但用实际行动表达关心的特点，体现了默默无闻的关爱。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '分析人物形象时只需要关注主要角色，次要人物对塑造主要人物没有作用。', NULL, 'F', '次要人物对主要人物起衬托、对比作用，有时还是情节发展的推动者，同样是人物分析的重要内容。', 2, 1);

-- --------------------------------------------------------------------------
-- 12. 语言品味与赏析
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='语言品味与赏析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '朱自清《荷塘月色》中"月光如流水一般，静静地泻在这一片叶子和花上"，赏析"泻"字的表达效果最恰当的是（　　）', '[{"key":"A","text":"写出了月光很亮"},{"key":"B","text":""泻"字化静为动，写出了月光如流水般倾泻的动态美"},{"key":"C","text":"用了夸张手法"},{"key":"D","text":"说明作者在倾倒东西"}]', 'B', '炼字赏析要从字的表达效果入手——"泻"本义是液体快速流下，用在这里让月光有了流动感，化静为动，生动传神。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '语言赏析中，"这个词能不能换成另一个词"这类问题的答题思路是（　　）', '[{"key":"A","text":"直接说不能换即可"},{"key":"B","text":"先表态(能否换)，再分析原词的表达效果和换后的效果差异"},{"key":"C","text":"说能换并写一个新词"},{"key":"D","text":"不回答"}]', 'B', '替换类赏析题的规范答题步骤：表明观点（不能换）→分析原词的表达效果→比较换词后的差异→总结。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '品味作品语言时，只需关注使用了修辞手法的句子，普通句子没有赏析价值。', NULL, 'F', '好的语言赏析既关注修辞句的精妙，也关注普通用词的准确生动——平淡中见真情也是语言魅力。', 2, 1);

-- --------------------------------------------------------------------------
-- 13. 主题理解与概括
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='主题理解与概括' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '概括文章主题最完整的表达方式是（　　）', '[{"key":"A","text":"只写文章讲了一个什么故事"},{"key":"B","text":""本文通过叙述……，表达了/表现了/批判了……""},{"key":"C","text":"抄写原文结尾段"},{"key":"D","text":"只写自己的感受"}]', 'B', '主题概括的规范结构是：内容概括（通过什么）+ 思想情感（表达了什么）。缺少任何一部分都不完整。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '《背影》中朱自清通过描写父亲买橘子的背影，表达的主要情感是（　　）', '[{"key":"A","text":"对父亲的抱怨"},{"key":"B","text":"对父亲衰老的感伤和对父爱的感激"},{"key":"C","text":"对旅游的怀念"},{"key":"D","text":"对橘子味道的回忆"}]', 'B', '《背影》的主题是父子亲情——通过对父亲爬月台买橘子这一细节的描写，表现父爱的深沉和作者的感动、愧疚与怀念。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '理解文章主题只需要关注文章的开头和结尾段就够了，中间内容不重要。', NULL, 'F', '文章主题往往通过全文层层递进、逐步深化，需要通读全文、综合分析，不能只看首尾段。', 2, 1);

-- ============================================================================
-- 三、常见文言实词虚词 (9 nodes × 3 = 27 questions)
-- ============================================================================

-- --------------------------------------------------------------------------
-- 14. 一词多义
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='一词多义' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"故"字在"故天将降大任于是人也"中的意思是（　　）', '[{"key":"A","text":"旧的"},{"key":"B","text":"所以"},{"key":"C","text":"老朋友"},{"key":"D","text":"原因"}]', 'B', '"故"有多个义项：旧的（温故知新）、所以（故天将降大任）、老朋友（故人西辞）、原因（何故）。此处表结果"所以"。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"绝"字在"忽然抚尺一下，群响毕绝"中的意思是（　　）', '[{"key":"A","text":"断绝"},{"key":"B","text":"消失"},{"key":"C","text":"横渡"},{"key":"D","text":"极"}]', 'B', '"绝"在文言文中义项丰富。此处"群响毕绝"意为各种声音都消失了。"绝"作"消失"讲常见于"灭绝""绝迹"。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"爱"在文言文中只有"喜爱"这一个意思，和现代汉语相同。', NULL, 'F', '"爱"在文言文中也有"吝惜""舍不得"的意思，如"齐国虽褊小，吾何爱一牛"中的"爱"意为"吝惜"。', 3, 1);

-- --------------------------------------------------------------------------
-- 15. 古今异义
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='古今异义' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"妻子"在古汉语中的意思是（　　）', '[{"key":"A","text":"仅指妻子"},{"key":"B","text":"妻子和儿女"},{"key":"C","text":"儿女"},{"key":"D","text":"指已婚女性"}]', 'B', '古汉语中"妻子"是两个词：妻（妻子）+ 子（儿女），泛指妻子儿女。今义缩小为仅指配偶。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"交通"在古汉语"阡陌交通，鸡犬相闻"中的意思是（　　）', '[{"key":"A","text":"交通运输"},{"key":"B","text":"交错相通"},{"key":"C","text":"交往沟通"},{"key":"D","text":"交通部门"}]', 'B', '"交通"古义为"交错相通"（阡陌指田间小路，交错相通），今义指各种运输和通信事业。词义发生了变化。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '古今异义词的判断标准是看这个词在古代和现代的意思是否不同。', NULL, 'T', '古今异义是指同一个词在古汉语和现代汉语中意义不同，如"走"古义为"跑"、"汤"古义为"热水"等。', 1, 1);

-- --------------------------------------------------------------------------
-- 16. 词类活用
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='词类活用' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"沛公军霸上"中"军"的活用类型是（　　）', '[{"key":"A","text":"名词作状语"},{"key":"B","text":"名词作动词（驻军）"},{"key":"C","text":"形容词作名词"},{"key":"D","text":"使动用法"}]', 'B', '"军"本义为名词"军队"，此处活用为动词"驻军"。名词作动词是词类活用中最常见的类型。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"孔子师郯子"中"师"的用法是（　　）', '[{"key":"A","text":"名词作动词，意为"以……为师""},{"key":"B","text":"名词作状语"},{"key":"C","text":"意动用法"},{"key":"D","text":"使动用法"}]', 'C', '"师"在这里是意动用法——以郯子为师（认为郯子是老师）。意动用法表示"认为……怎么样"或"把……当作……"。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '词类活用是指某个词在特定的语言环境中临时改变词性和用法。', NULL, 'T', '词类活用是古汉语的重要语法现象，是词语在具体语境中临时改变了语法功能，离开该语境后恢复原词性。', 1, 1);

-- --------------------------------------------------------------------------
-- 17. 通假字
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='通假字' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"学而时习之，不亦说乎"中"说"通哪个字（　　）', '[{"key":"A","text":"说（继续）"},{"key":"B","text":"悦（高兴）"},{"key":"C","text":"脱（脱离）"},{"key":"D","text":"税（税收）"}]', 'B', '"说"通"悦"，意为"高兴、愉快"。通假字是用音同或音近的字代替本字，"说"和"悦"在古代读音相近。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"师者，所以传道受业解惑也"中"受"通（　　）', '[{"key":"A","text":"收"},{"key":"B","text":"授（传授）"},{"key":"C","text":"首"},{"key":"D","text":"守"}]', 'B', '"受"通"授"，意为"传授"。韩愈《师说》中常用通假字，注意不要与现代汉语混淆。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '通假字是古人写错的字，没有任何规律可循，只能死记硬背。', NULL, 'F', '通假字有规律可循：多数是音同或音近的替代（如"说"通"悦"），也有字形相近的。归类记忆比死记硬背更高效。', 1, 1);

-- --------------------------------------------------------------------------
-- 18. 常见虚词（之·其·以·而）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='常见虚词（之·其·以·而）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"青，取之于蓝"中"之"的用法是（　　）', '[{"key":"A","text":"助词"的""},{"key":"B","text":"代词（代"青"）"},{"key":"C","text":"取消句子独立性"},{"key":"D","text":"动词"到""}]', 'B', '"之"在这里是代词，代指前面的"青"（靛青）。"取之于蓝"=从蓝草中提取它（靛青）。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"锲而不舍"中"而"表示的关系是（　　）', '[{"key":"A","text":"转折关系（却）"},{"key":"B","text":"承接关系（然后）"},{"key":"C","text":"修饰关系（地）"},{"key":"D","text":"并列关系（并且）"}]', 'B', '"锲而不舍"意为"不停地雕刻"，"而"连接"锲"和"不舍"两个连续动作，表承接关系（然后/接着）。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"以"在文言文中的用法包括介词（用/凭借）、连词（用来/因为）和动词（认为）。', NULL, 'T', '"以"的用法多样：介词"凭借""用"（以刀劈狼）；连词"用来"（以光先帝遗德）、"因为"（以其境过清）；动词"认为"（皆以美于徐公）。', 3, 1);

-- --------------------------------------------------------------------------
-- 19. 常见虚词（于·为·乃·则）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='常见虚词（于·为·乃·则）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"青，取之于蓝，而青于蓝"中两个"于"的意思分别是（　　）', '[{"key":"A","text":"从／比"},{"key":"B","text":"在／对于"},{"key":"C","text":"比／从"},{"key":"D","text":"被／在"}]', 'A', '第一个"于"表"从"（从蓝草中提取），第二个"于"表"比"（比蓝草更青）。相同虚词在不同语境中含义不同。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"乃"字在"乃不知有汉，无论魏晋"中的意思是（　　）', '[{"key":"A","text":"于是"},{"key":"B","text":"竟然"},{"key":"C","text":"才"},{"key":"D","text":"你的"}]', 'B', '"乃"有多个义项：于是（乃重修岳阳楼）、竟然（乃不知有汉）、才（乃悟前狼假寐）、你的（家祭无忘告乃翁）。此处表"竟然"的转折语气。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"则"在"学而不思则罔"中表示因果关系，相当于"就"。', NULL, 'T', '"则"在此处表承接/因果，连接"学而不思"和"罔"两个部分，意为"就""那么"。相当于"如果……就……"。', 2, 1);

-- --------------------------------------------------------------------------
-- 20. 文言句式（判断句·被动句）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='文言句式（判断句·被动句）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中属于判断句的是（　　）', '[{"key":"A","text":"战于长勺"},{"key":"B","text":"陈胜者，阳城人也"},{"key":"C","text":"何陋之有"},{"key":"D","text":"吾属今为之虏矣"}]', 'B', '"……者，……也"是判断句的典型标志。A是状语后置，C是宾语前置（倒装句），D是被动句（"为"表被动）。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中属于被动句的是（　　）', '[{"key":"A","text":"亚父者，范增也"},{"key":"B","text":"吾不能举全吴之地受制于人"},{"key":"C","text":"廉颇者，赵之良将也"},{"key":"D","text":"此则岳阳楼之大观也"}]', 'B', '"受制于人"中"于"引出动作的施动者"人"，表被动。A和C是判断句，D是判断句（"则"表判断）。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '文言判断句的标志性结构是"……者，……也"，此外还有用"乃""则""即"等表示的判断句。', NULL, 'T', '判断句的主要形式：①……者，……也（最典型）；②用"乃""则""即"等副词表判断；③无标志判断句。', 2, 1);

-- --------------------------------------------------------------------------
-- 21. 文言句式（倒装句·省略句）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='文言句式（倒装句·省略句）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"何陋之有"的正常语序是（　　）', '[{"key":"A","text":"有何陋"},{"key":"B","text":"陋有何"},{"key":"C","text":"有何之陋"},{"key":"D","text":"陋之有何"}]', 'A', '"何陋之有"是宾语前置句，用"之"作为提宾标志，正常语序为"有何陋"（有什么简陋的）。翻译时应还原。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中属于状语后置句的是（　　）', '[{"key":"A","text":"沛公安在"},{"key":"B","text":"战于长勺"},{"key":"C","text":"不亦说乎"},{"key":"D","text":"陈胜者，阳城人也"}]', 'B', '"战于长勺"正常语序应为"于长勺战"，介词结构"于长勺"放在动词后作补语，是状语后置（介宾短语后置）。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '省略句指文言文中省略主语、谓语、宾语或介词等成分的句子，翻译时需要补出省略成分。', NULL, 'T', '省略句是古汉语常见现象，省略主语（对话省）、省略宾语等，翻译时要根据上下文补出省略成分使语意完整。', 2, 1);

-- --------------------------------------------------------------------------
-- 22. 常见文言虚词（18个）：而何乎乃其且若所为焉也以因于与则者之
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='常见文言虚词（18个）：而何乎乃其且若所为焉也以因于与则者之' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '四川省对口高考要求掌握的常见文言虚词共有多少个（　　）', '[{"key":"A","text":"12个"},{"key":"B","text":"15个"},{"key":"C","text":"18个"},{"key":"D","text":"20个"}]', 'C', '四川省对口高考语文考纲规定考查18个常见文言虚词：而、何、乎、乃、其、且、若、所、为、焉、也、以、因、于、与、则、者、之。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"焉"在"积土成山，风雨兴焉"中的用法是（　　）', '[{"key":"A","text":"语气词（啊）"},{"key":"B","text":"兼词"于此"（从这里）"},{"key":"C","text":"疑问代词（哪里）"},{"key":"D","text":"连词（于是）"}]', 'B', '"焉"在这里是兼词，兼有介词"于"和代词"此"的意义，相当于"从这里/在这里"。风雨从这里兴起。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"者"字在文言文中可以构成"者"字结构，相当于现代汉语的"……的人""……的事物"。', NULL, 'T', '"者"是特殊的指示代词，通常附在动词、形容词后构成名词性短语，如"弈者"（下棋的人）、"来者"（来的人）。', 2, 1);

-- ============================================================================
-- 四、文言文翻译与理解 (7 nodes × 3 = 21 questions)
