-- --------------------------------------------------------------------------
-- 23. 翻译原则与步骤
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='翻译原则与步骤' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '文言文翻译的首要原则是（　　）', '[{"key":"A","text":"意译为主，直译为辅"},{"key":"B","text":"直译为主，意译为辅"},{"key":"C","text":"只直译不意译"},{"key":"D","text":"随意翻译即可"}]', 'B', '文言翻译以"信达雅"为标准，其中"信"（准确）要求直译为主，逐词对应；直译不通时才用意译。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '文言文翻译的第一步应该是（　　）', '[{"key":"A","text":"直接逐词翻译"},{"key":"B","text":"通读全文，把握上下文语境"},{"key":"C","text":"查字典找生字"},{"key":"D","text":"看译文参考"}]', 'B', '翻译的前提是理解。先通读全文把握大意和语境，再逐词对译，才能确保翻译准确，避免断章取义。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '文言文翻译的最高标准是"信达雅"——信（准确）、达（通顺）、雅（有文采）。', NULL, 'T', '"信达雅"是严复提出的翻译标准，也是文言文翻译的通用标准。"信"是第一位的，"达""雅"在此基础上追求。', 2, 1);

-- --------------------------------------------------------------------------
-- 24. 翻译技巧（留·补·换·调·删）
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='翻译技巧（留·补·换·调·删）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '翻译技巧"五字诀"中，对于古今意义相同的词应采用的技巧是（　　）', '[{"key":"A","text":"删（删掉不译）"},{"key":"B","text":"留（保留原词）"},{"key":"C","text":"换（换成现代词）"},{"key":"D","text":"补（补充省略）"}]', 'B', '"留"指保留不译的人名、地名、官名、年号等专有名词和古今意义相同的词，如"孔子""邯郸""太守"。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"沛公安在"翻译时首先应运用的技巧是（　　）', '[{"key":"A","text":"换——把"安"换成"哪里""},{"key":"B","text":"调——调整语序（"安在"→"在安"）"},{"key":"C","text":"补——补充主语"},{"key":"D","text":"删——删除"安""}]', 'B', '倒装句翻译先"调"——识别特殊句式，还原为现代汉语语序。"安在"是宾语前置（在安→在哪里），调整后翻译。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '翻译技巧"五字诀"包括：留（保留）、补（补充）、换（替换）、调（调整）、删（删除）。', NULL, 'T', '五字诀是文言翻译的实用技巧：保留专有名词、补充省略成分、替换古今异义词、调整倒装语序、删除无意义的发语词。', 1, 1);

-- --------------------------------------------------------------------------
-- 25. 文意理解与概括
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='文意理解与概括' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '概括《劝学》中心思想最准确的一项是（　　）', '[{"key":"A","text":"学习要努力"},{"key":"B","text":"论证学习的意义、作用和方法，勉励人们不断学习"},{"key":"C","text":"批评不学习的人"},{"key":"D","text":"学习可以改变命运"}]', 'B', '《劝学》从学习的意义（改变自己）、作用（弥补不足）、方法（积累坚持）三个层面系统论述"学不可以已"的主题。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '文意理解题中，"作者这样写有什么用意"属于（　　）', '[{"key":"A","text":"内容概括题"},{"key":"B","text":"写作意图分析题"},{"key":"C","text":"字词解释题"},{"key":"D","text":"背诵默写题"}]', 'B', '写作意图分析需要从内容和形式两方面思考：作者通过这样的写法想表达什么观点、达到什么效果或引发什么思考。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '文意理解只需要读懂文章的表面意思即可，不需要深入分析作者的写作意图和情感态度。', NULL, 'F', '文意理解包括表层理解（文章写了什么）和深层理解（为什么这样写、表达了什么情感态度），两者缺一不可。', 2, 1);

-- --------------------------------------------------------------------------
-- 26. 《廉颇蔺相如列传》精读
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='《廉颇蔺相如列传》精读' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '《廉颇蔺相如列传》中"完璧归赵"的主角是（　　）', '[{"key":"A","text":"廉颇"},{"key":"B","text":"赵王"},{"key":"C","text":"蔺相如"},{"key":"D","text":"秦王"}]', 'C', '蔺相如奉命出使秦国，凭借智慧和勇气使和氏璧完好无损地回到赵国。"完璧归赵"后来比喻将物品完好地归还原主。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"先国家之急而后私仇"体现了蔺相如怎样的品质（　　）', '[{"key":"A","text":"胆小怕事"},{"key":"B","text":"顾全大局、以国家利益为重"},{"key":"C","text":"争强好胜"},{"key":"D","text":"懦弱无能"}]', 'B', '面对廉颇的多次挑衅，蔺相如选择退让，因为他认为国家利益高于个人恩怨，体现了顾全大局的高尚品格。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '《廉颇蔺相如列传》中，廉颇最终负荆请罪，与蔺相如成为刎颈之交。', NULL, 'T', '廉颇得知蔺相如的良苦用心后，深感惭愧，光着上身背着荆条上门请罪。两人从此结为生死之交（刎颈之交）。', 1, 1);

-- --------------------------------------------------------------------------
-- 27. 《子路、曾皙、冉有、公西华侍坐》精读
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='《子路、曾皙、冉有、公西华侍坐》精读' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '在《子路、曾皙、冉有、公西华侍坐》中，孔子最赞同的弟子是（　　）', '[{"key":"A","text":"子路（治国强兵）"},{"key":"B","text":"冉有（使民富足）"},{"key":"C","text":"公西华（做小司仪）"},{"key":"D","text":"曾皙（暮春咏归）"}]', 'D', '曾皙描绘的"暮春者，春服既成……浴乎沂，风乎舞雩，咏而归"的礼乐治世画面，最符合孔子的政治理想，故孔子感叹"吾与点也"。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '《侍坐》中"摄乎大国之间"中"摄"的意思是（　　）', '[{"key":"A","text":"拍摄"},{"key":"B","text":"夹处（受到逼迫）"},{"key":"C","text":"整理"},{"key":"D","text":"代理"}]', 'B', '"摄"在此处意为"夹处""逼近"，指被夹在大国之间处境困难。联系上下文（千乘之国，摄乎大国之间）可推断。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '《子路、曾皙、冉有、公西华侍坐》记录了孔子和四位弟子谈论志向的场景。', NULL, 'T', '这篇文章是《论语》中的名篇，通过孔子启发四位弟子各言其志，展现了不同性格和志向，以及孔子的教育智慧。', 1, 1);

-- --------------------------------------------------------------------------
-- 28. 《劝学》精读
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='《劝学》精读' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '《劝学》中"青，取之于蓝，而青于蓝"用来论证（　　）', '[{"key":"A","text":"染料制作工艺"},{"key":"B","text":"学习可以超越原有水平"},{"key":"C","text":"颜色很好看"},{"key":"D","text":"蓝草比青色好"}]', 'B', '荀子用靛青从蓝草中提取却比蓝草更青的比喻，论证学习可以使人超越原有的水平，这是学习的意义。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '《劝学》的中心论点是（　　）', '[{"key":"A","text":"青出于蓝而胜于蓝"},{"key":"B","text":"学不可以已"},{"key":"C","text":"不积跬步无以至千里"},{"key":"D","text":"君子生非异也，善假于物也"}]', 'B', '"学不可以已"（学习不能停止）是《劝学》开篇提出的中心论点，全文围绕这一论点从意义、作用、方法三个层面展开。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '《劝学》中"锲而不舍，金石可镂"强调学习要有持之以恒的精神。', NULL, 'T', '荀子用雕刻的比喻论证坚持的重要性——只要坚持不懈地努力，即使是金石也可以雕刻成功。比喻学习需要恒心。', 1, 1);

-- --------------------------------------------------------------------------
-- 29. 《师说》精读
-- --------------------------------------------------------------------------
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='《师说》精读' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '《师说》中"师者，所以传道受业解惑也"中"受"的正确理解是（　　）', '[{"key":"A","text":"接受"},{"key":"B","text":"通"授"，传授"},{"key":"C","text":"受理"},{"key":"D","text":"遭受"}]', 'B', '"受"通"授"，意为"传授"。全句意为：老师是用来传授道理、教授学业、解答疑惑的人。这是韩愈对教师职责的定义。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '《师说》中提出的择师标准是（　　）', '[{"key":"A","text":"只看年龄大小"},{"key":"B","text":"道之所存，师之所存也"},{"key":"C","text":"只看地位高低"},{"key":"D","text":"只看是否有名气"}]', 'B', '"道之所存，师之所存也"意思是：道理所在的地方，就是老师所在的地方。韩愈主张以"道"为标准，不论身份贵贱年龄长幼。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '《师说》中韩愈批评了当时社会"耻学于师"的不良风气。', NULL, 'T', '韩愈写作《师说》的时代，士大夫阶层普遍以从师学习为耻。韩愈不顾流俗，倡导尊师重道，因此受到嘲笑和攻击。', 1, 1);


-- ============================================================================
-- 一、标点符号 (9 nodes × 4 = 36 questions)
-- ============================================================================

-- ==================================================================
-- 1. 顿号与逗号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='顿号与逗号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中顿号使用正确的一项是（　　）', '[{"key":"A","text":"我国科学、文化、艺术、卫生、教育、和新闻出版业有了很大发展。"},{"key":"B","text":"亚马逊河、尼罗河、密西西比河、和长江是世界四大河流。"},{"key":"C","text":"做月饼的馅料有核桃仁、花生仁、芝麻、青红丝等。"},{"key":"D","text":"他喜欢看《水浒》、《三国演义》、《西游记》、和《红楼梦》。"}]', 'C', 'A项"和教育"前顿号多余，并列词语最后两项之间用"和"不用顿号。B项"和长江"前顿号多余。D项书名号之间通常不用顿号。C项各成分是并列关系使用顿号正确。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，逗号使用不当的一项是（　　）', '[{"key":"A","text":"北京，是我们伟大祖国的首都。"},{"key":"B","text":"草原上，一群群牛羊在悠闲地吃草。"},{"key":"C","text":"他，今年十八岁，是一名中职学生。"},{"key":"D","text":"今天，天气，真好啊！"}]', 'D', 'D项"今天""天气"之间不是并列关系，不需要用逗号断开，读起来很破碎。正常应写作"今天天气真好啊！"', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中顿号使用错误的是（　　）', '[{"key":"A","text":"亚马逊河、尼罗河和密西西比河都是世界著名河流。"},{"key":"B","text":"全校三、四年级的学生参加了运动会。"},{"key":"C","text":"他最爱吃的水果有苹果、香蕉、葡萄、等等。"},{"key":"D","text":"这个路口一、三、五禁止左转。"}]', 'C', '"等"或"等等"前不应加顿号。C项"等等"是列举省略，前面不应再用顿号，应去掉顿号。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他最喜欢读的书有《论语》《孟子》《大学》《中庸》。"这句话中书名号之间可以不加顿号。', NULL, 'T', '书名号之间、引号之间通常可以不用顿号，直接连写即可。', 1, 1);

-- ==================================================================
-- 2. 分号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='分号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中分号使用正确的一项是（　　）', '[{"key":"A","text":"他从小喜欢读书；也喜欢运动。"},{"key":"B","text":"春天，桃花开了；夏天，荷花开了；秋天，菊花开了；冬天，梅花开了。"},{"key":"C","text":"这件事重要；我们必须做好。"},{"key":"D","text":"她性格开朗；学习认真；工作负责。"}]', 'B', '分号用于复句内部并列分句之间。B项四个分句是并列关系，使用分号正确。A、C、D项都是简单分句，用逗号即可，不应使用分号。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，分号使用不当的是（　　）', '[{"key":"A","text":"语言，人们用来抒情达意；文字，人们用来记言记事。"},{"key":"B","text":"出席会议的有教师代表；学生代表；家长代表。"},{"key":"C","text":"他考上了大学；我却落榜了；但他鼓励我继续努力。"},{"key":"D","text":"散文讲究形散神不散；小说则注重情节的完整性。"}]', 'B', 'B项"教师代表""学生代表""家长代表"是简单并列短语，用逗号或顿号即可，不应用分号。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他一边吃饭；一边看电视。"这句话中分号使用正确。', NULL, 'F', '"一边……一边……"连接的句子内部简单，用逗号即可，不应用分号。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '给下面句子选择正确的标点符号：\n我喜欢读小说（　）《红楼梦》让我着迷（　）我喜欢看散文（　）《背影》让我感动。', '[{"key":"A","text":"，，，，。"},{"key":"B","text":"；；；；。"},{"key":"C","text":"：；：；。"},{"key":"D","text":"：，：，。"}]', 'C', '"我喜欢读小说"后用冒号提示下文；"《红楼梦》让我着迷"后用分号，与后面"我喜欢看散文"构成并列关系。', 3, 1);

-- ==================================================================
-- 3. 问号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='问号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中问号使用正确的一项是（　　）', '[{"key":"A","text":"你了解什么是中职教育吗？"},{"key":"B","text":"我不知道他来不来？"},{"key":"C","text":"这件事该不该告诉他呢？我觉得应该告诉他。"},{"key":"D","text":"你从哪里来？我的朋友？"}]', 'A', 'A项是直接疑问句，用问号正确。B项"我不知道"是陈述句，不是疑问句，应该用句号。C项"这件事该不该告诉他呢"是选择问句，但后面"我觉得应该告诉他"是陈述，前半句也应改为逗号或句号。D项"你从哪里来，我的朋友"是称呼在后的疑问句，逗号应在称呼前。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，问号使用正确的是（　　）', '[{"key":"A","text":"今天几号了？我不知道。"},{"key":"B","text":"你是哪个学校的？同学？"},{"key":"C","text":"什么时候出发？坐什么车去？带什么东西？这些都要考虑好。"},{"key":"D","text":"这件事？能交给我去做？"}]', 'C', 'C项三个连续疑问句各用问号，后用句号结束全句，使用正确。A项"我不知道"是陈述语气，不应有问号。B项称呼在最后，应为"你是哪个学校的，同学？"。D项在"这件事"后加问号不正确。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"你难道不知道这样做是错的吗？"这句话是反问句，问号使用正确。', NULL, 'T', '"难道……吗"是典型的反问句式，用问号正确。反问句虽然不要求回答，但仍然属于疑问语气。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他问我明天去不去学校？"这句话的问号使用正确。', NULL, 'F', '这是一个间接引语（转述问句），不是直接提问，应该用句号：他问我明天去不去学校。', 2, 1);

-- ==================================================================
-- 4. 引号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='引号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中引号使用正确的一项是（　　）', '[{"key":"A","text":"他兴奋地说："明天我们就能出发了。"？"},{"key":"B","text":"妈妈问："你什么时候回家？""大概六点左右。"我回答。"},{"key":"C","text":"他果断地回答："这件事我没做过，也不了解。"他说完就走了。"},{"key":"D","text":"鲁迅在《故乡》中写道：‘其实地上本没有路，走的人多了，也便成了路。’"}]', 'D', 'D项引用鲁迅的话，使用引号正确。A项后引号后不应同时出现问号，应去掉问号或将问号放在引号内。B项引用对话时，"你什么时候回家？"和"大概六点左右"是连续对话，中间应使用逗号而非引号断开。C项引用的部分不完整，混合了叙述和引用，结构混乱。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中引号用法与其他三项不同的是（　　）', '[{"key":"A","text":"古人云："学不可以已。"},{"key":"B","text":"这就是所谓的"工匠精神"。"},{"key":"C","text":"老舍被誉为"人民艺术家"。"},{"key":"D","text":"这种"聪明"其实是自欺欺人。"}]', 'A', 'A项引号表示直接引用他人原话。B、C、D项的引号表示特殊含义或特定称谓。B项"工匠精神"是特定概念，C项"人民艺术家"是荣誉称号，D项"聪明"是反语。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他问我："你今天有空吗？""这句话的引号使用正确。', NULL, 'F', '句中已有冒号作提示，再用引号嵌套不当。直接引语内部不需要再用引号。正确写法为：他问我："你今天有空吗？"', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他说："这件事很重要"，并叮嘱我要认真对待。"这句话中标点符号使用正确。', NULL, 'F', '叙述人在引语中间断开时，前引号内的内容末尾应该用逗号而非句号，"这件事很重要"后的句号应改为逗号。', 2, 1);

-- ==================================================================
-- 5. 省略号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='省略号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中省略号使用正确的一项是（　　）', '[{"key":"A","text":"他翻开书本，开始朗读："春……夏……秋……冬……"},{"key":"B","text":"菜市场里有黄瓜、西红柿、土豆、茄子……等等。"},{"key":"C","text":"那个遥远的村庄……我至今难以忘怀。"},{"key":"D","text":"他支支吾吾地说："我……我……我不是故意的……"。"}]', 'D', 'D项省略号表示说话断断续续，使用正确。A项省略号不应在引号外，各季节之间用顿号或逗号即可。B项省略号和"等等"不能同时使用，二者选其一。C项"遥远的村庄"后无需用省略号表示停顿，应用逗号。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"教室里摆满了书架、桌椅、电脑……等教学设备。"这句话中的省略号和"等"可以同时使用。', NULL, 'F', '省略号和"等""等等"不能同时使用，二者功能重复，应去掉省略号或去掉"等"。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，省略号使用不当的是（　　）', '[{"key":"A","text":"词典可以告诉我们许多词语的含义，比如\\\"爱\\\"\\\"恨\\\"\\\"幸福\\\"……"},{"key":"B","text":"让我们点燃手中的蜡烛，为逝去的生命……祈祷。"},{"key":"C","text":"他一边走一边念叨着：\\\"如果当初……那么现在……哎。\\""},{"key":"D","text":"这件事你去做吧……不，还是让我来吧！"}]', 'B', 'B项"为逝去的生命……祈祷"中省略号使用不当，此处不需要表示省略或停顿。A项表示列举省略正确。C项表示思绪断断续续正确。D项"做吧"后用省略号表示犹豫，然后转折为"不"，使用正确。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '省略号占两个汉字的位置，即六个点（……），不能分两行。', NULL, 'T', '省略号用六个小圆点表示，占两个字的位置，中间不能断开换行。', 1, 1);

-- ==================================================================
-- 6. 破折号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='破折号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中破折号使用正确的一项是（　　）', '[{"key":"A","text":"亚洲——有世界上最高的山峰——珠穆朗玛峰。"},{"key":"B","text":"你今天要——注意安全——早点回家。"},{"key":"C","text":"他最喜欢的城市——成都——是一座来了就不想走的城市。"},{"key":"D","text":"这就是我——一个普普通通的中职学生——对未来——的展望。"}]', 'C', 'C项用破折号表示插入补充说明，"成都"是"最喜欢的城市"的具体说明，使用正确。A项破折号过度使用，"亚洲有世界上最高的山峰珠穆朗玛峰"不需要破折号。B项破折号用于夹注时表示强调，但"注意安全早点回家"不是夹注。D项"对未来"前用破折号无意义。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中破折号的用法是表示解释说明的一项是（　　）', '[{"key":"A","text":"今天天气真好啊——我们一起出去玩吧！"},{"key":"B","text":"中国古代四大发明——造纸术、印刷术、火药、指南针——对世界文明贡献巨大。"},{"key":"C","text":"他急匆匆地跑来——满头大汗——对我说：\\"快走！\\""},{"key":"D","text":"这个人——看起来很面熟——在哪里见过"}]', 'B', 'B项破折号表示解释说明——"造纸术、印刷术、火药、指南针"是对"四大发明"的具体解释。A项表示话题转换。C项表示补充说明状态。D项无意义。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '破折号与省略号一样，都占两个汉字的位置，但破折号是中间不断开的一条直线。', NULL, 'T', '破折号占两个汉字的位置，是一条不间断的直线（——），不同于省略号的六个点，也不能分两行书写。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他大声喊道："快跑——"话还没说完，石头就滚下来了。"这句话中的破折号表示声音的延长。', NULL, 'T', '破折号可用于表示声音的延长或拖音，"快跑——"表示声音被拉长，使用正确。', 1, 1);

-- ==================================================================
-- 7. 书名号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='书名号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中书名号使用正确的一项是（　　）', '[{"key":"A","text":"他最喜欢读《鲁迅全集》中的《狂人日记》。"},{"key":"B","text":"《今天我看了》一部很好看的电影。"},{"key":"C","text":"他写了一篇作文叫《我》的学校。"},{"key":"D","text":"这篇文章发表在《中国青年报》的《青春》栏目上。"}]', 'A', 'A项《鲁迅全集》是书名，《狂人日记》是篇名，书名号嵌套使用正确。B项"今天我看了"不是作品名称，不应加书名号。C项"我"的学校"不是书名，不应加书名号。D项"青春"是栏目名，非独立作品，一般不用书名号，可用引号。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '课程名称、活动名称、会议名称等应该使用书名号。', NULL, 'F', '课程名称、活动名称、会议名称等一般不用书名号，书名号主要用于书名、篇名、报刊名、文件名、影视作品名等。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列选项中，书名号使用不当的是（　　）', '[{"key":"A","text":"《红楼梦》是中国古典四大名著之一。"},{"key":"B","text":"他最喜欢唱《我和我的祖国》这首歌。"},{"key":"C","text":"本学期我们学习了《如何写好应用文》这个单元。"},{"key":"D","text":"这篇文章的标题是《青春与梦想》。"}]', 'C', 'C项"如何写好应用文"是教学单元名称，不应用书名号，可用引号或直接写。歌曲名（B）、书名（A）、文章标题（D）应用书名号。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"《人民日报》发表了题为《做新时代的有为青年》的评论员文章。"这句话中书名号使用正确。', NULL, 'T', '《人民日报》是报刊名，《做新时代的有为青年》是文章标题，两个都用书名号正确。', 1, 1);

-- ==================================================================
-- 8. 连接号与间隔号
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='连接号与间隔号' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中连接号使用正确的一项是（　　）', '[{"key":"A","text":"北京——成都的火车每天有十几趟。"},{"key":"B","text":"2019-2025年是我校快速发展的时期。"},{"key":"C","text":"这个机器人身高约1、8米。"},{"key":"D","text":"他住在北京市·海淀区。"}]', 'B', 'B项用短横连接号表示时间起止（2019-2025），使用正确。A项表地点起止可用一字线或短横，但用破折号不正确。C项"1、8米"应用小数点而非顿号。D项"北京市·海淀区"中间不应加间隔号。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，间隔号使用正确的是（　　）', '[{"key":"A","text":"他出生于2000·5·20。"},{"key":"B","text":"《念奴娇·赤壁怀古》是苏轼的代表作之一。"},{"key":"C","text":"北京·上海都是特大城市。"},{"key":"D","text":"他毕业于四川·成都·第七中学。"}]', 'B', 'B项间隔号用于词牌名和题目之间（《念奴娇·赤壁怀古》），使用正确。间隔号主要用于人名中间（如"约翰·列侬"）、书名与篇名之间等，不用于日期（A）、城市名（C、D）。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '间隔号（·）常用于外国人名中的名字与姓氏之间，如"迈克尔·乔丹"。', NULL, 'T', '间隔号用于音译的外国人名各部分之间，使用正确。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '连接号（—）和破折号（——）的写法是一样的，只是使用场景不同。', NULL, 'F', '连接号是一个字长或半字长的短线，破折号是两个字长的长线，二者形态和长度不同，不能混用。', 2, 1);

-- ==================================================================
-- 9. 标点符号综合辨析
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='标点符号综合辨析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，标点符号使用完全正确的一项是（　　）', '[{"key":"A","text":"我不知道他去不去？"},{"key":"B","text":"他是哪里人？我不太清楚。"},{"key":"C","text":"他问：\\"你去不去？\\"我点点头。"},{"key":"D","text":"你叫什么名字？我叫小明。"}]', 'C', 'C项引号内为直接问句使用问号，外部叙述使用句号，标点使用正确。A项间接引语不应有问号。B项前引号内"你去不去"是问句，引号外问号多余。D项引语末尾句号位置不对。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子标点使用完全正确的是（　　）', '[{"key":"A","text":"今天星期几？"},{"key":"B","text":"谁是我们的朋友？谁是我们的敌人？这是革命的首要问题。"},{"key":"C","text":"这本书、本子、和笔都在桌子上。"},{"key":"D","text":"超市里有水果……等等。"}]', 'B', 'B项连续两个疑问句各用问号，最后一个问句后用句号收束，使用正确。A项"是什么"后不应有问号。C项"书、本子"后用分号不当。D项省略号和"等等"重复。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '给下面句子选择正确的标点序号：\n老师常说（　）学习要持之以恒（　）不能三天打鱼（　）两天晒网（　）', '[{"key":"A","text":"：，，。"},{"key":"B","text":"：；；。"},{"key":"C","text":"，；；。"},{"key":"D","text":"：，。"}]', 'A', '冒号引出直接引述内容；"不能三天打鱼，两天晒网"是并列关系用逗号搭配合适；句号结束全句。A正确。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"她唱了一首《青春之歌》——这首歌让她想起了自己的学生时代。"这句话标点符号使用正确。', NULL, 'T', '书名号《青春之歌》表示歌曲名，破折号表示解释说明，标点使用正确。', 2, 1);

-- ============================================================================
-- 二、修辞手法辨析 (9 nodes × 4 = 36 questions)
-- ============================================================================

-- ==================================================================
-- 1. 比喻
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='比喻' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了比喻修辞手法的一项是（　　）', '[{"key":"A","text":"她的脸红得像苹果。"},{"key":"B","text":"她好像不喜欢这种安排。"},{"key":"C","text":"他长得像他爸爸。"},{"key":"D","text":"天色看起来像是要下雨了。"}]', 'A', 'A项将"脸"比作"苹果"，用了比喻词"像"，是明喻。B项"好像"表示推测，不是比喻。C项"像"表示比较（长相相似）。D项"像是"表示推测天气。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中属于暗喻的一项是（　　）', '[{"key":"A","text":"她的眼睛像星星一样明亮。"},{"key":"B","text":"书籍是屹立在时间汪洋中的灯塔。"},{"key":"C","text":"月亮像白玉盘挂在天上。"},{"key":"D","text":"教室里安静得针落地的声音都能听见。"}]', 'B', '暗喻用"是""成为""变成"等词连接本体和喻体，B项用"是"将"书籍"比作"灯塔"。A、C项是明喻（像）。D项是夸张。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他像一头倔强的牛，说什么也不肯回头。"这句话运用了比喻的修辞手法。', NULL, 'T', '将"他"比作"倔强的牛"，用比喻词"像"，是比喻中的明喻。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，属于借喻的一项是（　　）', '[{"key":"A","text":"小姑娘的脸像熟透的苹果。"},{"key":"B","text":"最可恨那些毒蛇猛兽，吃尽了我们的血肉。"},{"key":"C","text":"老师是园丁，我们就是花朵。"},{"key":"D","text":"月亮升起来了，像刚脱水而出的玉轮冰盘。"}]', 'B', '借喻不出现本体，直接用喻体代替本体。B项用"毒蛇猛兽"直接比喻剥削者/压迫者，本体（剥削者）不出现。A、D是明喻，C是暗喻。', 3, 1);

-- ==================================================================
-- 2. 比拟（拟人+拟物）
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='比拟（拟人+拟物）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了拟人修辞手法的一项是（　　）', '[{"key":"A","text":"花儿在风中笑弯了腰。"},{"key":"B","text":"他像一只离弦的箭冲了出去。"},{"key":"C","text":"教室里静悄悄的。"},{"key":"D","text":"太阳从东方升起来了。"}]', 'A', 'A项将"花儿"当作人来写，"笑弯了腰"是具有人的行为特征，是拟人。B项是比喻。C、D项是普通陈述。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，不属于拟人的一项是（　　）', '[{"key":"A","text":"春天迈着轻盈的步伐走来了。"},{"key":"B","text":"那棵老槐树在风中叹息着。"},{"key":"C","text":"这条小河清得像一面镜子。"},{"key":"D","text":"月亮躲进了云层里。"}]', 'C', 'C项将"小河"比作"镜子"，是比喻，不是拟人。A项"迈着步伐"、B项"叹息着"、D项"躲进了"都是赋予事物人的动作。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"这座山像一位巨人守卫着村庄。"这句话运用了拟人的修辞手法。', NULL, 'F', '这句话将山比作巨人，是比喻（暗喻），不是拟人。拟人需要赋予事物人的动作或情感，而这里只是用"像"作比较。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"风带着雨星，像在地上寻找什么似的，东一头西一头地乱撞。"这句话运用了拟人的修辞手法。', NULL, 'T', '"寻找""东一头西一头地乱撞"赋予了风和雨以人的动作和行为，是拟人的修辞手法。', 2, 1);

-- ==================================================================
-- 3. 借代
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='借代' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了借代修辞手法的一项是（　　）', '[{"key":"A","text":"她的脸蛋像红苹果一样"},{"key":"B","text":"太阳露出了笑脸"},{"key":"C","text":"不拿群众一针一线"},{"key":"D","text":"飞流直下三千尺"}]', 'C', 'C项"一针一线"用具体的物品代指一切财物，是借代（以部分代整体）。A项是比喻。B项是拟人。D项是夸张。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，借代手法运用不当的一项是（　　）', '[{"key":"A","text":"那位\\"长头发\\"走了过来"},{"key":"B","text":"红领巾们正在开展学雷锋活动"},{"key":"C","text":"白衣天使奋战在抗疫一线"},{"key":"D","text":"他笔耕不辍，用笔墨记录时代变迁"}]', 'A', 'A项"长头发"不能作为特定特征的借代，语义不明确。B项"红领巾"是少先队标志，代指少先队员，是特征代本体。C项"白衣天使"是特征代本体。D项"笔墨"代指文字或文章，是工具代本体。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"巾帼不让须眉"中运用的修辞手法是（　　）', '[{"key":"A","text":"比喻"},{"key":"B","text":"借代"},{"key":"C","text":"比拟"},{"key":"D","text":"对偶"}]', 'B', '"巾帼"是古代妇女的头巾和发饰，借代指女性；"须眉"是胡须和眉毛，借代指男性。两者都是借代，以特征代本体。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"我们要爱护校园里的一草一木。"这句话运用了借代的修辞手法。', NULL, 'F', '"一草一木"在这里是泛指校园里的各种物品，不是借代，而是泛指/列举。借代要有明确的"代"的关系。', 2, 1);

-- ==================================================================
-- 4. 夸张
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='夸张' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了夸张修辞手法的一项是（　　）', '[{"key":"A","text":"教室里安静得连针掉在地上的声音都能听见。"},{"key":"B","text":"他像一只兔子一样跑得很快。"},{"key":"C","text":"她的歌声很动听。"},{"key":"D","text":"今天是星期三。"}]', 'A', 'A项"针掉在地上的声音都能听见"极度夸大了安静的程度，是夸张。B项是比喻。C、D项是普通陈述。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，属于扩大的夸张的一项是（　　）', '[{"key":"A","text":"这块地方还没有巴掌大。"},{"key":"B","text":"他高兴得一蹦三尺高。"},{"key":"C","text":"她泪如雨下。"},{"key":"D","text":"白发三千丈，缘愁似个长。"}]', 'D', '"白发三千丈"是扩大的夸张，将白发长度夸大到不可能的程度，以突出愁思之深。A项是缩小的夸张（地方小到没巴掌大）。B项是扩大的夸张（一蹦三尺高），但程度不如D项典型。C项是比喻。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"危楼高百尺，手可摘星辰。"这句诗运用了夸张的修辞手法。', NULL, 'T', '"手可摘星辰"极度夸大了楼的高度，是扩大夸张。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"他的嗓子像铜钟一样洪亮。"这句话运用了夸张的修辞手法。', NULL, 'F', '这句话将"嗓子"比作"铜钟"，是比喻（明喻），不是夸张。夸张需要超过事实可能的极限。', 2, 1);

-- ==================================================================
-- 5. 对偶
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='对偶' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了对偶修辞手法的一项是（　　）', '[{"key":"A","text":"两个黄鹂鸣翠柳，一行白鹭上青天"},{"key":"B","text":"日照香炉生紫烟，遥看瀑布挂前川"},{"key":"C","text":"山朗润起来了，水涨起来了，太阳的脸红起来了"},{"key":"D","text":"他学习成绩很好，是班上第一名"}]', 'A', 'A项"两个"对"一行"，"黄鹂"对"白鹭"，"鸣"对"上"，"翠柳"对"青天"，对仗工整。B项"日照"对"瀑布"（名词对名词）、"香炉"对"三千"（"生紫烟"对"尺"不工整），结构上不完全工整。C项是排比。D项是普通陈述。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列选项中，对偶修辞手法与例句相同的一项是（　　）\n例句：横眉冷对千夫指，俯首甘为孺子牛。', '[{"key":"A","text":"两个黄鹂鸣翠柳，一行白鹭上青天"},{"key":"B","text":"日照香炉生紫烟，遥看瀑布挂前川"},{"key":"C","text":"山朗润起来了，水涨起来了，太阳的脸红起来了"},{"key":"D","text":"他学习成绩很好"}]', 'A', 'A项"两个"对"一行"，"黄鹂"对"白鹭"，"鸣"对"上"，"翠柳"对"青天"，对仗工整。B项"日照"对"瀑布"（名词对名词）、"香炉"对"三千"（"生紫烟"对"尺"不工整），结构上不完全工整。C项是排比。D项是普通陈述。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"日出江花红胜火，春来江水绿如蓝。"这两句诗运用了对偶的修辞手法。', NULL, 'T', '"日出"对"春来"，"江花"对"江水"，"红胜火"对"绿如蓝"，对仗工整。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"书山有路勤为径，学海无涯苦作舟。"这句话运用了对偶和比喻两种修辞手法。', NULL, 'T', '"书山"对"学海"，"有路"对"无涯"，"勤为径"对"苦作舟"，字数、结构、词性都工整，是对偶。同时"书山""学海"也是比喻。', 2, 1);

-- ==================================================================
-- 6. 排比
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='排比' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了排比修辞手法的一项是（　　）', '[{"key":"A","text":"两个黄鹂鸣翠柳，一行白鹭上青天"},{"key":"B","text":"飞流直下三千尺，疑是银河落九天"},{"key":"C","text":"我热爱这片土地，我热爱这片天空，我热爱这片海洋"},{"key":"D","text":"幸福是什么？幸福是一种内心的感受。"}]', 'C', 'C项连续三个"我热爱"开头的句子，结构相同、语气一致、意义相关，是排比。A项是对偶。B项是夸张。D项是设问。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列各句中，属于排比修辞的一项是（　　）', '[{"key":"A","text":"他好像明白了什么"},{"key":"B","text":"有的在跳舞，有的在唱歌，有的在弹琴，每个人都很开心"},{"key":"C","text":"书山有路勤为径，学海无涯苦作舟"},{"key":"D","text":"小草偷偷地从土里钻出来"}]', 'B', 'B项"有的……有的……有的……"三个结构相同的句子排列在一起，是排比。A项"好像"表示推测不是排比。C项三组对偶组成排比。D项是拟人。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"生活是一面镜子，你笑它也笑，你哭它也哭。"这句话运用了排比的修辞手法。', NULL, 'F', '这句话只有两个"你……它……"结构，不符合排比至少三项的要求，更接近对比或对偶。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"青春是人生中最美好的季节，青春是梦想开始的地方，青春是奋斗的黄金时期。"这句话运用了排比的修辞手法。', NULL, 'T', '三个"青春是……"开头的句子，是排比。', 1, 1);

-- ==================================================================
-- 7. 反问
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='反问' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了反问修辞手法的一项是（　　）', '[{"key":"A","text":"什么是幸福？幸福是一种内心的感受。"},{"key":"B","text":"难道学习不重要吗？"},{"key":"C","text":"你吃饭了吗？"},{"key":"D","text":"这本书是我昨天买的。"}]', 'B', 'B项"难道……吗"是典型的反问句式，用疑问的形式表达肯定（学习重要）。A项"是什么呢"后自答，是设问。C项是普通疑问句。D项是陈述句。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"这件事难道不是你做的吗？"这句话表达的意思是（　　）', '[{"key":"A","text":"这件事不是你做的。"},{"key":"B","text":"这件事是你做的。"},{"key":"C","text":"这件?"]', 'B', '反问"难道不是……吗"表达肯定的含义，意思就是"是你做的"。反问句以否定形式表达肯定，或以肯定形式表达否定。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"这难道不是一个伟大的奇迹吗？"这句话运用了反问的修辞手法。', NULL, 'T', '"难道……吗"是反问的标志句式，用疑问形式表达"这是一个伟大的奇迹"的肯定含义。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '反问与设问都是无疑而问，所以二者没有区别。', NULL, 'F', '反问和设问虽然都是"无疑而问"，但区别明显：设问是自问自答（引出下文），反问是问而不答（答案蕴含问句中）。', 2, 1);

-- ==================================================================
-- 8. 设问
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='设问' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中，运用了设问修辞手法的一项是（　　）', '[{"key":"A","text":"幸福是什么？是一种内心的感受。"},{"key":"B","text":"难道学习不重要吗？"},{"key":"C","text":"你吃饭了吗？"},{"key":"D","text":"太阳出来了。"}]', 'A', 'A项先问"幸福是什么"，然后自己回答"是一种感觉"，是典型的设问。B项是反问（问而不答）。C项是疑问句。D项是陈述句。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '设问修辞手法的主要作用是（　　）', '[{"key":"A","text":"增强语言气势，使观点更鲜明。"},{"key":"B","text":"引起读者注意，启发读者思考。"},{"key":"C","text":"使语言更加形象生动。"},{"key":"D","text":"使语言更加含蓄委婉。"}]', 'B', '设问的主要作用是"引人注意、启发思考"，通过自问自答引导读者思路。A项是排比/反问的作用。C项是比喻的作用。D项不是设问的作用。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"是谁创造了人类世界？是我们劳动群众。"这句话运用了设问的修辞手法。', NULL, 'T', '先提出问题，然后自己给出答案，是典型的设问。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"你难道不觉得这样做不对吗？"这句话运用了设问的修辞手法。', NULL, 'F', '"难道……吗"是反问句式，不是设问。设问是自问自答，反问是问中含答。', 2, 1);

-- ==================================================================
-- 9. 易混修辞辨析
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='易混修辞辨析（借代vs借喻/比喻vs比拟/对偶vs排比/设问vs反问）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列句子中属于借代而非借喻的一项是（　　）', '[{"key":"A","text":"中国人民没有被\\"毒蛇猛兽\\"吓倒"},{"key":"B","text":"她是照亮我们前行的\\"灯塔\\""},{"key":"C","text":"知识是黑夜中的\\"明灯\\""},{"key":"D","text":"\\"红领巾\\"们在公园里做义工"}]', 'D', '借代的本体和借体之间有相关性（特征代本体），借喻的本体和喻体之间有相似性。D项"红领巾"和"少先队员"是特征与实体的相关性，是借代。A、B、C项都是借喻（"毒蛇猛兽""灯塔""明灯"和实际事物之间有相似性）。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列对修辞手法的判断正确的一项是（　　）', '[{"key":"A","text":"\\"他像猴子一样敏捷\\"——运用了比拟手法"},{"key":"B","text":"\\"春天来了\\"——运用了比喻手法"},{"key":"C","text":"\\"歌声像一条小河，汇成了欢乐的海洋\\"——比喻手法"},{"key":"D","text":"\\"两个黄鹂鸣翠柳，一行白鹭上青天\\"——排比手法"}]', 'C', 'C项判断正确。"像一条小河"是比喻（明喻），"汇成了……歌声"是暗喻。A项应是"他像猴子"是比喻而非比拟（拟人是赋予物以人态，这里是形貌比较）。B项"来了"是拟人而非比喻。D项是对偶而非排比（只有两句，排比需至少三项）。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '对偶和排比的主要区别是（　　）', '[{"key":"A","text":"对偶字数必须相同，排比无字数要求。"},{"key":"B","text":"对偶成对出现（两项），排比至少三项。"},{"key":"C","text":"对偶可以用在诗中，排比不能。"},{"key":"D","text":"对偶只能写景，排比只能议论。"}]', 'B', '对偶是两句成对，要求结构相同、字数相等、意义相关；排比是三项或三项以上结构相似的句子排列。两项就是对偶，三项及以上可能是排比，也可能含对偶。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"难道你还不了解我吗？——我当然了解你。"前面是反问，后面是设问。', NULL, 'F', '前面"难道……吗"是反问，后面"我当然了解你"是补充说明，不是设问中的"自答"——设问是自己设问自己回答，这里是反问后的正常陈述。设问的核心是先问后答、问为引导。', 3, 1);

-- ============================================================================
-- 三、古诗词鉴赏 (7 nodes × 4 = 28 questions)
-- ============================================================================

-- ==================================================================
-- 1. 《诗经》选篇：关雎、蒹葭
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='《诗经》选篇：关雎、蒹葭' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"关关雎鸠，在河之洲"出自《诗经》中的哪一篇？（　　）', '[{"key":"A","text":"《蒹葭》"},{"key":"B","text":"《关雎》"},{"key":"C","text":"《静女》"},{"key":"D","text":"《采薇》"}]', 'B', '"关关雎鸠，在河之洲"是《诗经·关雎》的首句，描写水鸟鸣叫起兴，引出君子对淑女的追求。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"蒹葭苍苍，白露为霜。所谓伊人，在水一方。"这首诗主要表达的是（　　）', '[{"key":"A","text":"对恋人的热切追求"},{"key":"B","text":"对家乡的深切思念"},{"key":"C","text":"对理想境界的向往和可望而不可即的惆怅"},{"key":"D","text":"对友人远行的送别之情"}]', 'C', '《蒹葭》以"在水一方"的意象表达了对美好事物（伊人）可望而不可即的惆怅和执着追求，具有多重象征意义。', 2, 1),
('语文[职高]', @n, 'FILL_IN', '"关关雎鸠，在河之洲。窈窕淑女，___。"', NULL, '君子好逑', '《诗经·关雎》的名句。窈窕淑女是君子好的配偶。"逑"意为配偶。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"蒹葭苍苍，白露为霜"中的"为"字意思是"凝结成"。', NULL, 'T', '"白露为霜"意为晶莹的露水凝结成了霜，"为"在这里是"成为、凝结成"的意思。', 2, 1);

-- ==================================================================
-- 2. 唐诗鉴赏：将进酒、茅屋为秋风所破歌
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='唐诗鉴赏：将进酒、茅屋为秋风所破歌' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"天生我材必有用，千金散尽还复来"出自哪位诗人之手？（　　）', '[{"key":"A","text":"杜甫"},{"key":"B","text":"李白"},{"key":"C","text":"白居易"},{"key":"D","text":"王维"}]', 'B', '诗句出自李白的《将进酒》，表现了诗人自信豁达、不畏挫折的豪迈气概。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '《将进酒》中"君不见高堂明镜悲白发，朝如青丝暮成雪"表达的主要情感是（　　）', '[{"key":"A","text":"对青春易逝的悲伤和感慨"},{"key":"B","text":"对当时社会的不满"},{"key":"C","text":"对仕途不顺的抱怨"},{"key":"D","text":"对家乡的思念"}]', 'A', '"朝如青丝暮成雪"用夸张的手法极写人生短暂、青春易逝，表达了诗人对时光飞逝的感慨，也暗含了及时行乐的态度。', 2, 1),
('语文[职高]', @n, 'FILL_IN', '"安得广厦千万间，___天下寒士俱欢颜"出自杜甫《茅屋为秋风所破歌》。', NULL, '大庇', '杜甫在《茅屋为秋风所破歌》中表达了自己虽身处困境却心怀天下的博大情怀。"大庇"意为广泛地庇护。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '李白是唐代伟大的现实主义诗人，被誉为"诗圣"。', NULL, 'F', '李白是浪漫主义诗人，被誉为"诗仙"。"诗圣"是杜甫。', 1, 1);

-- ==================================================================
-- 3. 宋词鉴赏：念奴娇·赤壁怀古、雨霖铃
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='宋词鉴赏：念奴娇·赤壁怀古、雨霖铃' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"大江东去，浪淘尽，千古风流人物"出自哪首词？（　　）', '[{"key":"A","text":"《雨霖铃》"},{"key":"B","text":"《念奴娇·赤壁怀古》"},{"key":"C","text":"《江城子》"},{"key":"D","text":"《声声慢》"}]', 'B', '句出苏轼的《念奴娇·赤壁怀古》，开篇以长江东去起兴，引发对历史英雄的缅怀。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"今宵酒醒何处？杨柳岸，晓风残月"出自哪位词人之手？（　　）', '[{"key":"A","text":"苏轼"},{"key":"B","text":"柳永"},{"key":"C","text":"辛弃疾"},{"key":"D","text":"李清照"}]', 'B', '句出柳永的《雨霖铃·寒蝉凄切》，以"杨柳岸，晓风残月"的凄美意象表达离别后的孤寂凄凉。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '苏轼《念奴娇·赤壁怀古》中写道："人生如梦，___。"', NULL, '一尊还酹江月', '"一尊还酹江月"意为一杯酒洒在地上祭奠江中的明月。"酹"读lèi，是洒酒祭奠的意思。"尊"通"樽"，酒杯。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '苏轼和柳永都是宋代豪放词派的代表词人。', NULL, 'F', '苏轼是豪放词派的代表，但柳永是婉约词派的代表，《雨霖铃》是其婉约风格的代表作。', 1, 1);

-- ==================================================================
-- 4. 诗歌意象与意境分析
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='诗歌意象与意境分析' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列意象中，通常与"愁思"相关的一组是（　　）', '[{"key":"A","text":"杨柳、明月、美酒"},{"key":"B","text":"战鼓、红旗、刀剑"},{"key":"C","text":"江水、孤鸿、落叶"},{"key":"D","text":"荷花、清泉、幽兰"}]', 'C', '在中国古典诗歌中，江水（"问君能有几多愁，恰似一江春水向东流"）、孤鸿（孤雁）、落叶（秋意萧瑟）都是表达愁思的经典意象。A项"美酒"常与豪迈相关。B项"战鼓"与战争相关。D项"荷花"与高洁品质相关。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"大漠孤烟直，长河落日圆"营造的意境特点是（　　）', '[{"key":"A","text":"雄浑壮阔"},{"key":"B","text":"凄清冷寂"},{"key":"C","text":"清新明丽"},{"key":"D","text":"幽静深远"}]', 'A', '"大漠""长河""落日"等意象组合，展现出大漠广袤无垠、落日雄浑壮丽的画面，意境雄浑壮阔。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '意象是融合了诗人主观情感的客观物象，意境是多个意象组合形成的整体氛围。', NULL, 'T', '意象是诗歌的基本元素，是"意"（情感）和"象"（物象）的结合。意境是多个意象共同营造出的整体艺术氛围和境界。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"枯藤老树昏鸦，小桥流水人家"一句中运用的主要表现手法是（　　）', '[{"key":"A","text":"比喻"},{"key":"B","text":"意象叠加"},{"key":"C","text":"拟人"},{"key":"D","text":"借代"}]', 'B', '马致远《天净沙·秋思》中，名词意象直接排列（枯藤、老树、昏鸦、小桥、流水、人家），无连接词，这种手法叫"意象叠加"或"列锦"，通过意象组合营造意境。', 3, 1);

-- ==================================================================
-- 5. 诗歌表达技巧（抒情方式/描写手法/修辞）
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='诗歌表达技巧（抒情方式/描写手法/修辞）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列诗句中，属于借景抒情的一项是（　　）', '[{"key":"A","text":"感时花溅泪，恨别鸟惊心"},{"key":"B","text":"人生自古谁无死，留取丹心照汗青"},{"key":"C","text":"至今思项羽，不肯过江东"},{"key":"D","text":"去年今日此门中，人面桃花相映红"}]', 'A', 'A项通过描写"花溅泪""鸟惊心"的景色来表达忧国忧民之情，是借景抒情。B项直接抒情（直抒胸臆）。C项用典和抒情。D项是叙述。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"遥想公瑾当年，小乔初嫁了，雄姿英发"运用的表现手法是（　　）', '[{"key":"A","text":"借古讽今"},{"key":"B","text":"虚实结合"},{"key":"C","text":"托物言志"},{"key":"D","text":"衬托"}]', 'B', '苏轼在《念奴娇·赤壁怀古》中"遥想公瑾当年"是虚写（回忆历史），与现实的"早生华发"形成虚实对比。', 3, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"感时花溅泪，恨别鸟惊心"运用了拟人的修辞手法。', NULL, 'T', '"花溅泪""鸟惊心"赋予花和鸟以人的情感（感伤时花也流泪、鸟也心惊），是拟人。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '直抒胸臆是直接表达感情，借景抒情是借助景物表达感情，二者不能在一首诗中共存。', NULL, 'F', '一首诗中常同时运用多种抒情方式。例如《将进酒》既有借景抒情（"君不见黄河之水天上来"），也有直抒胸臆（"天生我材必有用"）。', 2, 1);

-- ==================================================================
-- 6. 诗歌思想情感与观点态度
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='诗歌思想情感与观点态度' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '杜甫在《茅屋为秋风所破歌》中表达的核心思想是（　　）', '[{"key":"A","text":"对自己命运不济的哀叹"},{"key":"B","text":"对当时社会黑暗的控诉"},{"key":"C","text":"推己及人、兼济天下的博大情怀"},{"key":"D","text":"思念远方的亲人"}]', 'C', '"安得广厦千万间，大庇天下寒士俱欢颜"表达了杜甫虽自身困顿却心系天下苍生的高尚情怀，由个人的痛苦推及到天下寒士。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '李白《将进酒》中"人生得意须尽欢，莫使金樽空对月"体现的人生态度是（　　）', '[{"key":"A","text":"悲观消极、及时行乐"},{"key":"B","text":"热爱生活、珍惜当下、乐观豪迈"},{"key":"C","text":"逃避现实、醉生梦死"},{"key":"D","text":"看破红尘、淡泊名利"}]', 'B', '李白劝人"须尽欢"不是消极享乐，而是在认识到人生短暂后的积极态度——热爱生活、珍惜当下、乐观自信。', 2, 1),
('语文[职高]', @n, 'FILL_IN', '"安得广厦千万间，大庇天下___俱欢颜"（杜甫《茅屋为秋风所破歌》）。', NULL, '寒士', '"寒士"指贫寒的读书人，衍生指所有贫苦之人。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"长风破浪会有时，直挂云帆济沧海"表达了诗人乐观自信、不畏困难的人生态度。', NULL, 'T', '句出李白《行路难》，"长风破浪"比喻克服困难，"直挂云帆济沧海"表示勇往直前、实现理想的决心，体现了乐观进取的态度。', 1, 1);

-- ==================================================================
-- 7. 诗歌语言赏析（炼字/诗眼/风格）
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='诗歌语言赏析（炼字/诗眼/风格）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '"春风又绿江南岸"中"绿"字的妙处在于（　　）', '[{"key":"A","text":"用了绿色这个形容词，生动形象"},{"key":"B","text":"形容词用作动词，化静为动，写出春天到来的过程"},{"key":"C","text":"绿色比别的颜色好看"},{"key":"D","text":"只是为了押韵"}]', 'B', '"绿"字形容词活用为动词，既写出了春风吹过后江南岸变绿的过程和结果，又充满色彩感和画面感。王安石经过多次推敲才选定"绿"字，是炼字的经典例子。', 3, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '李白的诗歌风格特点主要是（　　）', '[{"key":"A","text":"沉郁顿挫"},{"key":"B","text":"豪放飘逸"},{"key":"C","text":"婉约含蓄"},{"key":"D","text":"清新自然"}]', 'B', '李白诗歌风格以"豪放飘逸"著称，想象奇特、气势磅礴、语言奔放。A项"沉郁顿挫"是杜甫的风格。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"诗眼"是指一首诗中最能体现诗人情感、最具表现力的关键词句。', NULL, 'T', '诗眼是诗歌中最精练传神、最能体现诗歌主旨和诗人情感的字词或句子，往往起到画龙点睛的作用。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '杜甫被称为"诗圣"，其诗被称为"诗史"，诗歌风格以豪放飘逸著称。', NULL, 'F', '杜甫诗风是"沉郁顿挫"而非"豪放飘逸"。"豪放飘逸"是李白的特点。', 1, 1);

-- ============================================================================
-- 四、文学常识与名句默写 (7 nodes × 4 = 28 questions)
-- ============================================================================

-- ==================================================================
-- 1. 先秦诗文默写：静女、采薇、侍坐、寡人之于国、劝学
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='先秦诗文默写：静女、采薇、侍坐、寡人之于国、劝学' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'FILL_IN', '"昔我往矣，___。今我来思，雨雪霏霏。"（《诗经·采薇》）', NULL, '杨柳依依', '"杨柳依依"写当年出征时杨柳随风飘拂的样子，以乐景写哀情，是千古名句。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '"青，取之于蓝，___；冰，水为之，而寒于水。"（《劝学》）', NULL, '而青于蓝', '这句话以"青出于蓝"比喻学生可以超过老师或后人可以超越前人。注意两个"于"的含义不同——前"于"是"从"，后"于"是"比"。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '"故不积跬步，___；不积小流，无以成江海。"（《劝学》）', NULL, '无以至千里', '"故不积跬步，无以至千里"强调积累的重要性。"跬"读kuǐ，半步；"至"不写"致"。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"静女其姝，俟我于城隅"出自《诗经·采薇》。', NULL, 'F', '"静女其姝，俟我于城隅"出自《诗经·邶风·静女》，不是《采薇》。《采薇》的名句是"昔我往矣，杨柳依依"。', 1, 1);

-- ==================================================================
-- 2. 唐宋诗文默写：师说、将进酒、琵琶行、念奴娇、雨霖铃
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='唐宋诗文默写：师说、将进酒、琵琶行、念奴娇、雨霖铃' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'FILL_IN', '"师者，所以___解惑也。"（韩愈《师说》）', NULL, '传道受业', '韩愈《师说》开篇指出老师的职责——传授道理、教授学业、解答疑惑。"受"通"授"，不写"授"。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '"同是天涯沦落人，___。"（白居易《琵琶行》）', NULL, '相逢何必曾相识', '白居易《琵琶行》中的名句，慨叹彼此命运相似，"沦落"指流落漂泊。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '"大江东去，浪淘尽，___。"（苏轼《念奴娇·赤壁怀古》）', NULL, '千古风流人物', '苏轼开篇以长江东去起兴，引出对历史上英雄人物的追忆。"淘"不写"陶"。"风流人物"指杰出人物。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"千呼万唤始出来，犹抱琵琶半遮面"出自韩愈的《师说》。', NULL, 'F', '此句出自白居易的《琵琶行》，描写琵琶女在众人呼唤下迟疑出场的场景，并非韩愈《师说》中的句子。', 1, 1);

-- ==================================================================
-- 3. 宋文默写：六国论
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='宋文默写：六国论' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'FILL_IN', '"六国破灭，非兵不利，战不善，___。"（苏洵《六国论》）', NULL, '弊在赂秦', '苏洵《六国论》开篇立论：六国灭亡的原因不在于武器不锋利、仗打得不好，而在于割地贿赂秦国。', 2, 1),
('语文[职高]', @n, 'FILL_IN', '"以地事秦，犹___，薪不尽，火不灭。"（苏洵《六国论》）', NULL, '抱薪救火', '这句话用"抱薪救火"比喻割地赂秦的危害——割让土地给秦国就像抱着柴草去救火，柴草不烧完火就不会灭。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '苏洵《六国论》中"弊在赂秦"的"赂"是什么意思？（　　）', '[{"key":"A","text":"贿赂"},{"key":"B","text":"赠送财物"},{"key":"C","text":"割让土地"},{"key":"D","text":"赔偿"}]', 'B', '"赂"本意为送财物给人，在《六国论》中指六国以割让土地的方式讨好秦国，这里应理解为"赠送财物（土地）"。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '《六国论》是苏洵所写的史论文章，论述六国灭亡的原因在于"弊在赂秦"。', NULL, 'T', '苏洵《六国论》的中心论点是"六国破灭，弊在赂秦"，借古讽今，告诫北宋统治者不要对辽和西夏纳贡求和。', 2, 1);

-- ==================================================================
-- 4. 现代诗歌默写：我爱这土地、雨巷、致橡树
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='现代诗歌默写：我爱这土地、雨巷、致橡树' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'FILL_IN', '"为什么我的眼里常含泪水？___……"（艾青《我爱这土地》）', NULL, '因为我对这土地爱得深沉', '艾青《我爱这土地》的结尾，以饱含深情的诗句表达了对祖国的热爱。这是全诗最动人的名句。', 1, 1),
('语文[职高]', @n, 'FILL_IN', '"撑着油纸伞，独自彷徨在悠长，悠长又寂寥的___，我希望逢着一个丁香一样的结着愁怨的姑娘。"（戴望舒《雨巷》）', NULL, '雨巷', '戴望舒《雨巷》中"雨巷"是核心意象，象征迷惘、寂寥的心境，"丁香一样的姑娘"象征着美好而难以企及的理想。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '舒婷《致橡树》中"我必须是你近旁的一株木棉，作为树的形象和你站在一起"表达的爱情观是（　　）', '[{"key":"A","text":"依附顺从"},{"key":"B","text":"对立斗争"},{"key":"C","text":"平等独立、相互扶持"},{"key":"D","text":"无私奉献、不求回报"}]', 'C', '舒婷在《致橡树》中表达了现代女性追求平等、独立的爱情观——不是藤蔓依附大树，而是以"木棉"的姿态与"橡树"并肩站立、相互扶持。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '艾青的《我爱这土地》、戴望舒的《雨巷》、舒婷的《致橡树》都是中国现代诗歌的代表作。', NULL, 'T', '三首诗都是现代诗歌史上的重要作品。《我爱这土地》写于抗战时期，《雨巷》是象征主义代表作，《致橡树》是朦胧诗代表作。', 1, 1);

-- ==================================================================
-- 5. 文学体裁常识（诗歌/散文/小说/戏剧）
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='文学体裁常识（诗歌/散文/小说/戏剧）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列作品中，属于散文体裁的一项是（　　）', '[{"key":"A","text":"鲁迅《祝福》"},{"key":"B","text":"朱自清《荷塘月色》"},{"key":"C","text":"曹禺《雷雨》"},{"key":"D","text":"老舍《茶馆》"}]', 'B', '朱自清的《荷塘月色》是抒情散文。A项鲁迅《祝福》是小说（短篇小说）。C项曹禺《雷雨》是话剧（戏剧）。D项老舍《茶馆》是话剧（戏剧）。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '小说三要素是指（　　）', '[{"key":"A","text":"开头、发展、结尾"},{"key":"B","text":"时间、地点、人物"},{"key":"C","text":"人物、情节、环境"},{"key":"D","text":"起因、经过、结果"}]', 'C', '小说的三要素是人物（角色形象）、情节（故事发展）、环境（时代背景和具体场景），其中人物是小说的核心。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '文学体裁的"四分法"把文学分为诗歌、散文、小说、戏剧四大类。', NULL, 'T', '"四分法"是中国现代文学理论对文学作品的基本分类方式，将文学分为诗歌、散文、小说、戏剧四种体裁。', 1, 1),
('语文[职高]', @n, 'TRUE_FALSE', '剧本是戏剧演出的基础，必须有尖锐的矛盾冲突和个性化的人物语言。', NULL, 'T', '剧本必须具备两个核心要素：尖锐、集中的矛盾冲突和符合人物身份、性格的个性化语言。没有冲突就没有戏剧。', 2, 1);

-- ==================================================================
-- 6. 重要作家作品（古今中外）
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='重要作家作品（古今中外）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '下列作家与作品对应正确的一项是（　　）', '[{"key":"A","text":"鲁迅——《子夜》"},{"key":"B","text":"茅盾——《呐喊》"},{"key":"C","text":"老舍——《骆驼祥子》"},{"key":"D","text":"巴金——《雷雨》"}]', 'C', '老舍的《骆驼祥子》描写了北京人力车夫祥子的悲惨命运。A项《子夜》是茅盾的作品。B项《呐喊》是鲁迅的作品。D项《雷雨》是曹禺的作品。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '被誉为"俄国革命的一面镜子"的作家是（　　）', '[{"key":"A","text":"普希金"},{"key":"B","text":"列夫·托尔斯泰"},{"key":"C","text":"契诃夫"},{"key":"D","text":"高尔基"}]', 'B', '列夫·托尔斯泰被称为"俄国革命的一面镜子"，代表作有《战争与和平》《安娜·卡列尼娜》《复活》。A项普希金是俄国诗人。C项契诃夫是短篇小说大师。D项高尔基是社会主义现实主义文学奠基人。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '下列属于莎士比亚四大悲剧之一的是（　　）', '[{"key":"A","text":"《威尼斯商人》"},{"key":"B","text":"《罗密欧与朱丽叶》"},{"key":"C","text":"《哈姆雷特》"},{"key":"D","text":"《仲夏夜之梦》"}]', 'C', '莎士比亚四大悲剧是《哈姆雷特》《奥赛罗》《李尔王》《麦克白》。《威尼斯商人》和《仲夏夜之梦》是喜剧，《罗密欧与朱丽叶》是悲剧但不在"四大"之列。', 2, 1),
('语文[职高]', @n, 'TRUE_FALSE', '"史家之绝唱，无韵之离骚"是鲁迅对《史记》的评价。', NULL, 'T', '鲁迅高度评价司马迁的《史记》为"史家之绝唱，无韵之离骚"，既肯定其史学价值，也赞美其文学成就。', 1, 1);

-- ==================================================================
-- 7. 文化常识（称谓/历法/官职/科举/地理）
-- ==================================================================
SET @n = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND level=4 AND name='文化常识（称谓/历法/官职/科举/地理）' LIMIT 1);
INSERT IGNORE INTO question_bank (subject, category_id, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
('语文[职高]', @n, 'SINGLE_CHOICE', '古人称谓中，"弱冠"指的是多少岁的男子？（　　）', '[{"key":"A","text":"十五岁"},{"key":"B","text":"二十岁"},{"key":"C","text":"三十岁"},{"key":"D","text":"四十岁"}]', 'B', '古代男子二十岁行冠礼表示成年，称为"弱冠"。A项十五岁为"束发"。C项三十岁为"而立"。D项四十岁为"不惑"。', 2, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '中国古代科举考试中，殿试的第一名称为（　　）', '[{"key":"A","text":"进士"},{"key":"B","text":"解元"},{"key":"C","text":"会元"},{"key":"D","text":"状元"}]', 'D', '明清科举制度中，殿试录取分三甲：一甲三名赐"进士及第"，第一名"状元"、第二名"榜眼"、第三名"探花"。二甲赐"进士出身"，三甲赐"同进士出身"。', 1, 1),
('语文[职高]', @n, 'SINGLE_CHOICE', '"江表"在古代指的是（　　）', '[{"key":"A","text":"崤山以东地区"},{"key":"B","text":"函谷关以西地区"},{"key":"C","text":"长江以南地区"},{"key":"D","text":"黄河以北地区"}]', 'C', '"江表"指长江以南地区。从中原看，长江以南在长江之外，故称"江表"。A项"山东"在古文中指崤山以东。B项"关中"指函谷关以西地区。D项"河北"泛指黄河以北。', 3, 1);
COMMIT;
